/**
 * Deterministic synergy roster search. Does not mutate the game.
 * The score is the sum of combat synergy channels (or a subset of them).
 */
import { TEAM_SYNERGIES } from '../../constants/balance/teamSynergies.js';
import { RARITY } from '../../constants/core.ts';
import { SYNERGY_REGION_ORDER, type TeamSynergyDef } from '../../constants/balance/teamSynergies/types.ts';
import { getEggNativeRegionIdForSpecies } from '../../constants/balance/eggRegionMap.ts';
import type { GameRuntime } from '../types/game.js';
import {
    aggregateSynergyEffects,
    getActiveSynergyEntries,
    isSynergyActiveForTeam,
    type SynergyBonuses,
    type TeamSynergyMember,
} from './teamSynergyEvaluation.ts';
import { isSynergyRegionUnlocked } from './synergyRegionUnlock.ts';

export const SYNERGY_OBJECTIVE_KEYS = [
    'attack_mult',
    'spattack_mult',
    'defense_mult',
    'spdefense_mult',
    'max_hp_mult',
    'speed_mult',
    'heal_mult',
    'exp_mult',
    'pokedollars_mult',
] as const;

export type SynergyObjectiveKey = (typeof SYNERGY_OBJECTIVE_KEYS)[number];

const MULT_KEYS = new Set<string>([
    'attack_mult',
    'spattack_mult',
    'defense_mult',
    'spdefense_mult',
    'max_hp_mult',
    'speed_mult',
    'exp_mult',
]);

const FILTER_TO_KEY: Record<string, SynergyObjectiveKey> = {
    hp: 'max_hp_mult',
    atk: 'attack_mult',
    spatk: 'spattack_mult',
    def: 'defense_mult',
    spdef: 'spdefense_mult',
    spd: 'speed_mult',
    heal: 'heal_mult',
    exp: 'exp_mult',
    money: 'pokedollars_mult',
};

const MAX_EVALS = 25_000;
const LOCAL_PASSES = 6;
const PRUNED_CAP = 60;

export interface SynergyObjective {
    /** `null` sums every combat channel. */
    keys: readonly SynergyObjectiveKey[] | null;
}

export const SYNERGY_DRAW_RARITIES = [
    RARITY.COMMON,
    RARITY.RARE,
    RARITY.EPIC,
    RARITY.LEGENDARY,
] as const;

const DRAW_RARITY_SET = new Set<string>(SYNERGY_DRAW_RARITIES);
const DRAW_REGION_SET = new Set<string>(SYNERGY_REGION_ORDER);

export interface SynergyOptimizerMember {
    uid: string;
    name: string;
    type: string;
    secondaryType?: string | null;
    zone: 'team' | 'storage' | 'pension';
    combatPower: number;
    /** Missing or unknown rarities stay drawable. */
    rarity?: string;
}

export interface SynergyCandidateSource {
    uid?: string;
    name?: string;
    type?: string;
    secondaryType?: string | null;
    maxHp?: number;
    attack?: number;
    defense?: number;
    speed?: number;
    spattack?: number;
    spdefense?: number;
    level?: number;
    prestige?: number;
    rarity?: string;
}

export interface SynergyRosterMove {
    uid: string;
    name: string;
}

export interface SynergyRosterProposal {
    uids: string[];
    score: number;
    currentScore: number;
    changeCount: number;
    added: SynergyRosterMove[];
    removed: SynergyRosterMove[];
    gainedSynergyIds: string[];
    lostSynergyIds: string[];
    statDelta: Partial<Record<SynergyObjectiveKey, number>>;
}

export interface SynergyOptimizeResult {
    best: SynergyRosterProposal;
    adjust: SynergyRosterProposal | null;
}

export interface OptimizeSynergyInput {
    members: readonly SynergyOptimizerMember[];
    objective: SynergyObjective;
    includeStorage: boolean;
    includePension: boolean;
    maxTeamSize: number;
    /** Team uids that must stay. Unknown uids are ignored. */
    pinnedUids?: readonly string[];
    /** Box and daycare rarities that may be drawn. Omitted means all four. */
    allowedRarities?: readonly string[];
    /** Box and daycare native regions that may be drawn. Omitted means all nine. */
    allowedRegions?: readonly string[];
    game?: GameRuntime | null;
}

/** Visible rounds for a manual best-team search. */
export const SYNERGY_DEEP_ROUNDS = 50;

export interface SynergyRoundInfo {
    round: number;
    roundCount: number;
    /** Real synergy score, same unit as the card (0.25 is +25%). */
    bestScore: number;
    names: string[];
}

export interface SynergySearchOptions {
    /** Defaults to {@link SYNERGY_DEEP_ROUNDS}. `0` only computes the one-or-two-change step. */
    rounds?: number;
    onRound?: (info: SynergyRoundInfo) => void;
}

export interface SynergyDeepSearch {
    readonly roundCount: number;
    next(): SynergyRoundInfo | null;
    result(): SynergyOptimizeResult;
}

export interface SynergySlotSubstitute {
    uid: string;
    name: string;
    combatPower: number;
}

export function synergyRosterSearchKey(args: {
    members: readonly SynergyOptimizerMember[];
    objective: SynergyObjective;
    includeStorage: boolean;
    includePension: boolean;
    maxTeamSize: number;
    pinnedUids: readonly string[];
    unlockedRegions: readonly string[];
    allowedRarities?: readonly string[];
    allowedRegions?: readonly string[];
}): string {
    const keys = args.objective.keys ? args.objective.keys.join(',') : '*';
    const regions = args.unlockedRegions.slice().sort().join(',');
    const pins = args.pinnedUids.slice().sort().join(',');
    const rarities = allowedDrawRarities(args.allowedRarities).slice().sort().join(',');
    const nativeRegions = allowedDrawRegions(args.allowedRegions).slice().sort().join(',');
    const members = args.members.slice().sort((a, b) => (a.uid < b.uid ? -1 : a.uid > b.uid ? 1 : 0));
    const lines = [
        args.includeStorage ? '1' : '0',
        args.includePension ? '1' : '0',
        String(Math.max(1, Math.floor(args.maxTeamSize) || 1)),
        keys,
        regions,
        pins,
        rarities,
        nativeRegions,
    ];
    for (let i = 0; i < members.length; i++) {
        const member = members[i];
        if (!member) continue;
        lines.push(`${member.uid}|${member.name}|${member.type}|${member.secondaryType ?? ''}|${member.zone}|${member.combatPower}|${member.rarity ?? ''}`);
    }
    return lines.join('\n');
}

function allowedDrawRarities(ids: readonly string[] | undefined): string[] {
    if (!ids) return SYNERGY_DRAW_RARITIES.slice();
    const allowed: string[] = [];
    for (let i = 0; i < ids.length; i++) {
        const id = ids[i];
        if (id && DRAW_RARITY_SET.has(id) && !allowed.includes(id)) allowed.push(id);
    }
    return allowed;
}

function rarityBlocksDraw(member: SynergyOptimizerMember, allowed: ReadonlySet<string>): boolean {
    if (member.zone === 'team') return false;
    const rarity = member.rarity;
    if (!rarity || !DRAW_RARITY_SET.has(rarity)) return false;
    return !allowed.has(rarity);
}

function allowedDrawRegions(ids: readonly string[] | undefined): string[] {
    if (!ids) return SYNERGY_REGION_ORDER.slice();
    const allowed: string[] = [];
    for (let i = 0; i < ids.length; i++) {
        const id = ids[i];
        if (id && DRAW_REGION_SET.has(id) && !allowed.includes(id)) allowed.push(id);
    }
    return allowed;
}

function regionBlocksDraw(member: SynergyOptimizerMember, allowed: ReadonlySet<string>): boolean {
    if (member.zone === 'team') return false;
    const native = getEggNativeRegionIdForSpecies(member.name);
    if (!native || !DRAW_REGION_SET.has(native)) return false;
    return !allowed.has(native);
}

export function objectiveFromStatFilters(ids: readonly string[]): SynergyObjective {
    if (ids.length === 0) return { keys: null };
    const keys: SynergyObjectiveKey[] = [];
    for (let i = 0; i < ids.length; i++) {
        const key = FILTER_TO_KEY[ids[i] ?? ''];
        if (key && !keys.includes(key)) keys.push(key);
    }
    return { keys: keys.length > 0 ? keys : null };
}

export function scoreSynergyBonuses(bonuses: SynergyBonuses, objective: SynergyObjective): number {
    const keys = objective.keys ?? SYNERGY_OBJECTIVE_KEYS;
    let sum = 0;
    for (let i = 0; i < keys.length; i++) {
        const key = keys[i];
        if (!key) continue;
        const value = bonuses[key];
        sum += MULT_KEYS.has(key) ? value - 1 : value;
    }
    return sum;
}

export function synergyCombatPower(creature: SynergyCandidateSource): number {
    const raw =
        (Number(creature.maxHp) || 0) +
        (Number(creature.attack) || 0) +
        (Number(creature.defense) || 0) +
        (Number(creature.speed) || 0) +
        (Number(creature.spattack) || 0) +
        (Number(creature.spdefense) || 0);
    if (raw > 0) return raw;
    const level = Math.max(1, Math.floor(Number(creature.level) || 1));
    const prestige = Math.max(0, Math.floor(Number(creature.prestige) || 0));
    return level * 10 + prestige * 50;
}

export function collectSynergyCandidates(
    team: readonly SynergyCandidateSource[],
    storage: readonly SynergyCandidateSource[],
    pension: readonly SynergyCandidateSource[],
    isExcluded?: (uid: string) => boolean,
): SynergyOptimizerMember[] {
    const out: SynergyOptimizerMember[] = [];
    const seen = new Set<string>();
    const pushZone = (list: readonly SynergyCandidateSource[], zone: SynergyOptimizerMember['zone']) => {
        for (let i = 0; i < list.length; i++) {
            const creature = list[i];
            if (!creature) continue;
            const uid = String(creature.uid || '');
            const name = String(creature.name || '');
            const type = String(creature.type || '');
            if (!uid || !name || !type || seen.has(uid)) continue;
            if (isExcluded?.(uid)) continue;
            seen.add(uid);
            const secondary = creature.secondaryType ? String(creature.secondaryType) : null;
            const rarity = creature.rarity ? String(creature.rarity) : '';
            out.push({
                uid,
                name,
                type,
                secondaryType: secondary,
                zone,
                combatPower: synergyCombatPower(creature),
                ...(rarity ? { rarity } : {}),
            });
        }
    };
    pushZone(team, 'team');
    pushZone(storage, 'storage');
    pushZone(pension, 'pension');
    return out;
}

interface Instance {
    uid: string;
    combatPower: number;
    fromTeam: boolean;
}

interface Arch {
    key: string;
    name: string;
    type: string;
    secondary: string | null;
    native: string | null;
    affinity: number;
    instances: Instance[];
}

interface Pick {
    uid: string;
    name: string;
    type: string;
    secondaryType: string | null;
    combatPower: number;
    fromTeam: boolean;
    arch: Arch;
}

interface Task {
    id: string;
    def: TeamSynergyDef;
    weight: number;
    slots: number;
}

interface Metrics {
    picks: Pick[];
    micro: number;
    overlap: number;
    sym: number;
    power: number;
    uidKey: string;
}

function toMicro(score: number): number {
    return Math.round(score * 1e6);
}

function effectWeight(def: TeamSynergyDef, keys: ReadonlySet<string> | null): number {
    const effect = def.effect;
    if (!effect) return 0;
    let weight = 0;
    for (const key of Object.keys(effect)) {
        const val = effect[key];
        if (typeof val !== 'number' || val <= 0) continue;
        if (keys && !keys.has(key)) continue;
        if (MULT_KEYS.has(key) || key === 'heal_mult' || key === 'pokedollars_mult') weight += val;
    }
    return weight;
}

function estimateSlots(def: TeamSynergyDef): number {
    let speciesSlots = 0;
    const rule = def.requiredSpecies;
    if (rule?.species?.length) {
        const minCount = Math.max(1, Math.floor(Number(rule.minCount) || 1));
        speciesSlots = minCount >= rule.species.length ? rule.species.length : minCount;
    }
    let typeSlots = 0;
    if (def.types?.length && def.min_count) {
        typeSlots = def.all_required ? def.min_count * def.types.length : def.min_count;
    }
    return Math.max(1, speciesSlots, typeSlots);
}

function archCovers(arch: Arch, type: string, def: TeamSynergyDef): boolean {
    if (def.regionalTypesOnly === true && arch.native !== def.regionId) return false;
    return arch.type === type || arch.secondary === type;
}

function cmpWeight(a: Task, b: Task): number {
    if (b.weight !== a.weight) return b.weight - a.weight;
    return a.id < b.id ? -1 : a.id > b.id ? 1 : 0;
}

function cmpEff(a: Task, b: Task): number {
    const ea = a.weight / a.slots;
    const eb = b.weight / b.slots;
    if (eb !== ea) return eb - ea;
    return a.id < b.id ? -1 : a.id > b.id ? 1 : 0;
}

function rotate(list: readonly Task[], offset: number): Task[] {
    if (list.length === 0) return [];
    const n = ((offset % list.length) + list.length) % list.length;
    return list.slice(n).concat(list.slice(0, n));
}

function takeInstance(arch: Arch, used: Set<string>): Instance | null {
    const list = arch.instances;
    for (let i = 0; i < list.length; i++) {
        const inst = list[i];
        if (inst && !used.has(inst.uid)) return inst;
    }
    return null;
}

function toPick(arch: Arch, inst: Instance): Pick {
    return {
        uid: inst.uid,
        name: arch.name,
        type: arch.type,
        secondaryType: arch.secondary,
        combatPower: inst.combatPower,
        fromTeam: inst.fromTeam,
        arch,
    };
}

function typeGapMap(def: TeamSynergyDef, picks: readonly Pick[]): Map<string, number> {
    const gaps = new Map<string, number>();
    const types = def.types;
    const minCount = def.min_count;
    if (!types?.length || !minCount) return gaps;
    const counts: Record<string, number> = {};
    for (let i = 0; i < picks.length; i++) {
        const pick = picks[i];
        if (!pick) continue;
        if (def.regionalTypesOnly === true && pick.arch.native !== def.regionId) continue;
        if (pick.type) counts[pick.type] = (counts[pick.type] || 0) + 1;
        if (pick.secondaryType) counts[pick.secondaryType] = (counts[pick.secondaryType] || 0) + 1;
    }
    if (def.all_required) {
        for (let i = 0; i < types.length; i++) {
            const type = types[i];
            if (!type) continue;
            const gap = minCount - (counts[type] || 0);
            if (gap > 0) gaps.set(type, gap);
        }
        return gaps;
    }
    let bestType = '';
    let bestGap = Infinity;
    for (let i = 0; i < types.length; i++) {
        const type = types[i];
        if (!type) continue;
        const gap = minCount - (counts[type] || 0);
        if (gap <= 0) return gaps;
        if (gap < bestGap) {
            bestGap = gap;
            bestType = type;
        }
    }
    if (bestType) gaps.set(bestType, bestGap);
    return gaps;
}

function coverage(arch: Arch, gaps: Map<string, number>, def: TeamSynergyDef): number {
    let cover = 0;
    for (const [type, gap] of gaps) {
        if (gap > 0 && archCovers(arch, type, def)) cover += 1;
    }
    return cover;
}

function betterPick(
    arch: Arch,
    inst: Instance,
    cover: number,
    best: { arch: Arch; inst: Instance; cover: number } | null,
): boolean {
    if (!best) return true;
    if (cover !== best.cover) return cover > best.cover;
    if (inst.combatPower !== best.inst.combatPower) return inst.combatPower > best.inst.combatPower;
    if (arch.affinity !== best.arch.affinity) return arch.affinity > best.arch.affinity;
    return inst.uid < best.inst.uid;
}

function rollback(picks: Pick[], mark: number, used: Set<string>): void {
    while (picks.length > mark) {
        const removed = picks.pop();
        if (removed) used.delete(removed.uid);
    }
}

function metricsOf(picks: readonly Pick[], micro: number, original: Set<string>): Metrics {
    let overlap = 0;
    let power = 0;
    const uids: string[] = [];
    for (let i = 0; i < picks.length; i++) {
        const pick = picks[i];
        if (!pick) continue;
        if (original.has(pick.uid)) overlap += 1;
        power += pick.combatPower;
        uids.push(pick.uid);
    }
    const removed = original.size - overlap;
    const added = picks.length - overlap;
    uids.sort();
    return {
        picks: picks as Pick[],
        micro,
        overlap,
        sym: added + removed,
        power,
        uidKey: uids.join('|'),
    };
}

function betterMetrics(a: Metrics, b: Metrics): boolean {
    if (a.micro !== b.micro) return a.micro > b.micro;
    if (a.overlap !== b.overlap) return a.overlap > b.overlap;
    if (a.sym !== b.sym) return a.sym < b.sym;
    if (a.power !== b.power) return a.power > b.power;
    return a.uidKey < b.uidKey;
}

function changeCount(picks: readonly Pick[], original: Set<string>): number {
    let overlap = 0;
    for (let i = 0; i < picks.length; i++) {
        const pick = picks[i];
        if (pick && original.has(pick.uid)) overlap += 1;
    }
    return Math.max(picks.length - overlap, original.size - overlap);
}

function keepsPinned(picks: readonly Pick[], pinned: ReadonlySet<string>): boolean {
    if (pinned.size === 0) return true;
    let found = 0;
    for (let i = 0; i < picks.length; i++) {
        const uid = picks[i]?.uid;
        if (uid && pinned.has(uid)) found += 1;
        if (found === pinned.size) return true;
    }
    return false;
}

function orderTeam(currentUids: readonly string[], picks: readonly Pick[]): string[] {
    const chosen = new Map<string, Pick>();
    for (let i = 0; i < picks.length; i++) {
        const pick = picks[i];
        if (pick) chosen.set(pick.uid, pick);
    }
    const used = new Set<string>();
    const holes: number[] = [];
    const result: string[] = [];
    for (let i = 0; i < currentUids.length; i++) {
        const uid = currentUids[i] ?? '';
        if (chosen.has(uid)) {
            result.push(uid);
            used.add(uid);
        } else {
            holes.push(result.length);
            result.push('');
        }
    }
    const newcomers: Pick[] = [];
    for (let i = 0; i < picks.length; i++) {
        const pick = picks[i];
        if (pick && !used.has(pick.uid)) newcomers.push(pick);
    }
    newcomers.sort((a, b) => b.combatPower - a.combatPower || (a.uid < b.uid ? -1 : 1));
    let n = 0;
    for (let i = 0; i < holes.length; i++) {
        const hole = holes[i];
        const next = newcomers[n];
        if (hole === undefined || !next) break;
        result[hole] = next.uid;
        n += 1;
    }
    const compact: string[] = [];
    for (let i = 0; i < result.length; i++) {
        const uid = result[i];
        if (uid) compact.push(uid);
    }
    for (; n < newcomers.length; n++) {
        const next = newcomers[n];
        if (next) compact.push(next.uid);
    }
    return compact;
}

function slotCombos(slotCount: number, take: number): number[][] {
    const out: number[][] = [];
    if (take <= 0 || take > slotCount) return out;
    const cur: number[] = [];
    const walk = (start: number): void => {
        if (cur.length === take) {
            out.push(cur.slice());
            return;
        }
        for (let i = start; i < slotCount; i++) {
            cur.push(i);
            walk(i + 1);
            cur.pop();
        }
    };
    walk(0);
    return out;
}

function uniquePicks(picks: readonly Pick[]): boolean {
    const seen = new Set<string>();
    for (let i = 0; i < picks.length; i++) {
        const uid = picks[i]?.uid;
        if (!uid || seen.has(uid)) return false;
        seen.add(uid);
    }
    return true;
}

export function optimizeSynergyRoster(
    input: OptimizeSynergyInput,
    options?: SynergySearchOptions,
): SynergyOptimizeResult {
    const rounds = options?.rounds ?? SYNERGY_DEEP_ROUNDS;
    const search = openSynergyDeepSearch(input, rounds);
    for (;;) {
        const info = search.next();
        if (!info) break;
        options?.onRound?.(info);
    }
    return search.result();
}

function drawablePool(input: OptimizeSynergyInput): SynergyOptimizerMember[] {
    const seen = new Set<string>();
    const pool: SynergyOptimizerMember[] = [];
    const drawRarities = new Set(allowedDrawRarities(input.allowedRarities));
    const drawRegions = new Set(allowedDrawRegions(input.allowedRegions));
    for (let i = 0; i < input.members.length; i++) {
        const member = input.members[i];
        if (!member?.uid || !member.name || !member.type || seen.has(member.uid)) continue;
        if (member.zone === 'storage' && !input.includeStorage) continue;
        if (member.zone === 'pension' && !input.includePension) continue;
        if (member.zone !== 'team' && member.zone !== 'storage' && member.zone !== 'pension') continue;
        if (rarityBlocksDraw(member, drawRarities)) continue;
        if (regionBlocksDraw(member, drawRegions)) continue;
        seen.add(member.uid);
        pool.push(member);
    }
    return pool;
}

function activeSynergyKey(members: TeamSynergyMember[], game: GameRuntime | null): string {
    const ids: string[] = [];
    const active = getActiveSynergyEntries(members, game);
    for (let i = 0; i < active.length; i++) {
        const id = active[i]?.id;
        if (id) ids.push(id);
    }
    ids.sort();
    return ids.join('|');
}

function asSynergyMember(member: SynergyOptimizerMember): TeamSynergyMember {
    return {
        name: member.name,
        type: member.type,
        secondaryType: member.secondaryType ?? null,
    };
}

/** Copies that keep the same active synergies when they replace one roster slot. */
export function synergySlotSubstitutes(
    input: OptimizeSynergyInput & { rosterUids: readonly string[]; slotUid: string },
): SynergySlotSubstitute[] {
    const slotUid = input.slotUid;
    if (!slotUid) return [];
    const byUid = new Map<string, SynergyOptimizerMember>();
    for (let i = 0; i < input.members.length; i++) {
        const member = input.members[i];
        if (member?.uid && !byUid.has(member.uid)) byUid.set(member.uid, member);
    }
    const roster: SynergyOptimizerMember[] = [];
    const rosterSet = new Set<string>();
    for (let i = 0; i < input.rosterUids.length; i++) {
        const uid = input.rosterUids[i];
        if (!uid || rosterSet.has(uid)) continue;
        const member = byUid.get(uid);
        if (!member) continue;
        rosterSet.add(uid);
        roster.push(member);
    }
    const slot = byUid.get(slotUid);
    if (!slot || !rosterSet.has(slotUid)) return [];
    const game = input.game ?? null;
    const baseline: TeamSynergyMember[] = [];
    for (let i = 0; i < roster.length; i++) {
        const member = roster[i];
        if (member) baseline.push(asSynergyMember(member));
    }
    const target = activeSynergyKey(baseline, game);
    const pool = drawablePool(input);
    const bestByKey = new Map<string, SynergyOptimizerMember>();
    for (let i = 0; i < pool.length; i++) {
        const member = pool[i];
        if (!member || rosterSet.has(member.uid)) continue;
        const secondary = member.secondaryType ?? '';
        const key = `${member.name}|${member.type}|${secondary}`;
        const prev = bestByKey.get(key);
        if (!prev) {
            bestByKey.set(key, member);
            continue;
        }
        if (member.combatPower > prev.combatPower) {
            bestByKey.set(key, member);
            continue;
        }
        if (member.combatPower === prev.combatPower && member.uid < prev.uid) {
            bestByKey.set(key, member);
        }
    }
    const out: SynergySlotSubstitute[] = [];
    for (const copy of bestByKey.values()) {
        const swapped: TeamSynergyMember[] = [];
        for (let i = 0; i < roster.length; i++) {
            const member = roster[i];
            if (!member) continue;
            swapped.push(member.uid === slotUid ? asSynergyMember(copy) : asSynergyMember(member));
        }
        if (activeSynergyKey(swapped, game) !== target) continue;
        out.push({ uid: copy.uid, name: copy.name, combatPower: copy.combatPower });
    }
    out.sort((a, b) => {
        if (b.combatPower !== a.combatPower) return b.combatPower - a.combatPower;
        return a.uid < b.uid ? -1 : a.uid > b.uid ? 1 : 0;
    });
    return out;
}

export function openSynergyDeepSearch(
    input: OptimizeSynergyInput,
    rounds = SYNERGY_DEEP_ROUNDS,
): SynergyDeepSearch {
    const game = input.game ?? null;
    const maxSize = Math.max(1, Math.floor(input.maxTeamSize) || 1);
    const keySet: ReadonlySet<string> | null = input.objective.keys ? new Set(input.objective.keys) : null;
    const pool = drawablePool(input);

    const arches: Arch[] = [];
    const archByKey = new Map<string, Arch>();
    for (let i = 0; i < pool.length; i++) {
        const member = pool[i];
        if (!member) continue;
        const secondary = member.secondaryType || null;
        const key = `${member.name}|${member.type}|${secondary ?? ''}`;
        let arch = archByKey.get(key);
        if (!arch) {
            arch = {
                key,
                name: member.name,
                type: member.type,
                secondary,
                native: getEggNativeRegionIdForSpecies(member.name),
                affinity: 0,
                instances: [],
            };
            archByKey.set(key, arch);
            arches.push(arch);
        }
        arch.instances.push({
            uid: member.uid,
            combatPower: member.combatPower,
            fromTeam: member.zone === 'team',
        });
    }
    for (let i = 0; i < arches.length; i++) {
        arches[i]?.instances.sort((a, b) => {
            if (b.combatPower !== a.combatPower) return b.combatPower - a.combatPower;
            if (a.fromTeam !== b.fromTeam) return a.fromTeam ? -1 : 1;
            return a.uid < b.uid ? -1 : a.uid > b.uid ? 1 : 0;
        });
    }

    const tasks = buildTasks(arches, game, keySet);
    for (let i = 0; i < arches.length; i++) {
        const arch = arches[i];
        if (arch) arch.affinity = affinityOf(arch, tasks);
    }
    const pruned = pruneArchetypes(arches, tasks);

    const originalPicks: Pick[] = [];
    const originalUids: string[] = [];
    const original = new Set<string>();
    for (let i = 0; i < pool.length; i++) {
        const member = pool[i];
        if (!member || member.zone !== 'team') continue;
        const secondary = member.secondaryType || null;
        const arch = archByKey.get(`${member.name}|${member.type}|${secondary ?? ''}`);
        if (!arch) continue;
        const inst = arch.instances.find((item) => item.uid === member.uid);
        if (!inst) continue;
        originalPicks.push(toPick(arch, inst));
        originalUids.push(member.uid);
        original.add(member.uid);
    }

    const pinned = new Set<string>();
    const requestedPins = input.pinnedUids ?? [];
    for (let i = 0; i < requestedPins.length; i++) {
        const uid = requestedPins[i];
        if (uid && original.has(uid)) pinned.add(uid);
    }

    const memberBuf: TeamSynergyMember[] = [];
    const cache = new Map<string, number>();
    let evals = 0;

    const membersOf = (picks: readonly Pick[]): TeamSynergyMember[] => {
        memberBuf.length = picks.length;
        for (let i = 0; i < picks.length; i++) {
            const pick = picks[i];
            if (!pick) continue;
            let slot = memberBuf[i];
            if (!slot) {
                slot = { name: pick.name, type: pick.type, secondaryType: pick.secondaryType };
                memberBuf[i] = slot;
            } else {
                slot.name = pick.name;
                slot.type = pick.type;
                slot.secondaryType = pick.secondaryType;
            }
        }
        return memberBuf;
    };

    const nameScratch = new Map<string, number>();
    const typeScratch: Record<string, number> = {};
    const typeSeen: string[] = [];
    const regionalScratch: Record<string, number> = {};
    const regionalSeen: string[] = [];

    const evalMicro = (picks: readonly Pick[]): number | null => {
        const cacheKey = picks.map((pick) => pick.uid).sort().join('|');
        const hit = cache.get(cacheKey);
        if (hit !== undefined) return hit;
        if (evals >= MAX_EVALS) return null;
        evals += 1;
        const micro = toMicro(scorePicks(picks, tasks, nameScratch, typeScratch, typeSeen, regionalScratch, regionalSeen));
        cache.set(cacheKey, micro);
        return micro;
    };

    const activeNow = (picks: readonly Pick[], def: TeamSynergyDef): boolean => {
        return isSynergyActiveForTeam(def, membersOf(picks), game);
    };

    const chooseArch = (
        predicate: (arch: Arch) => boolean,
        gaps: Map<string, number>,
        def: TeamSynergyDef,
        used: Set<string>,
    ): Pick | null => {
        let best: { arch: Arch; inst: Instance; cover: number } | null = null;
        for (let i = 0; i < arches.length; i++) {
            const arch = arches[i];
            if (!arch || !predicate(arch)) continue;
            const inst = takeInstance(arch, used);
            if (!inst) continue;
            const cover = coverage(arch, gaps, def);
            if (!betterPick(arch, inst, cover, best)) continue;
            best = { arch, inst, cover };
        }
        return best ? toPick(best.arch, best.inst) : null;
    };

    const addSpecies = (picks: Pick[], used: Set<string>, def: TeamSynergyDef): boolean => {
        const rule = def.requiredSpecies;
        if (!rule?.species?.length) return true;
        const minCount = Math.max(1, Math.floor(Number(rule.minCount) || 1));
        const names = rule.species;
        const gaps = typeGapMap(def, picks);
        if (minCount >= names.length) {
            for (let i = 0; i < names.length; i++) {
                const name = names[i];
                if (!name || picks.some((pick) => pick.name === name)) continue;
                if (picks.length >= maxSize) return false;
                const chosen = chooseArch((arch) => arch.name === name, gaps, def, used);
                if (!chosen) return false;
                used.add(chosen.uid);
                picks.push(chosen);
            }
            return names.every((name) => picks.some((pick) => pick.name === name));
        }
        let matched = 0;
        for (let i = 0; i < picks.length; i++) {
            const pick = picks[i];
            if (pick && names.includes(pick.name)) matched += 1;
        }
        let guard = 0;
        while (matched < minCount && guard < 8) {
            guard += 1;
            if (picks.length >= maxSize) return false;
            const chosen = chooseArch((arch) => names.includes(arch.name), gaps, def, used);
            if (!chosen) return false;
            used.add(chosen.uid);
            picks.push(chosen);
            matched += 1;
        }
        return matched >= minCount;
    };

    const addTypes = (picks: Pick[], used: Set<string>, def: TeamSynergyDef): boolean => {
        if (!def.types?.length || !def.min_count) return true;
        let guard = 0;
        while (guard < 8) {
            guard += 1;
            const gaps = typeGapMap(def, picks);
            if (gaps.size === 0) return true;
            if (picks.length >= maxSize) return false;
            const chosen = chooseArch(() => true, gaps, def, used);
            if (!chosen || coverage(chosen.arch, gaps, def) <= 0) return false;
            used.add(chosen.uid);
            picks.push(chosen);
        }
        return typeGapMap(def, picks).size === 0;
    };

    const tryComplete = (picks: Pick[], used: Set<string>, task: Task): void => {
        if (activeNow(picks, task.def)) return;
        if (picks.length >= maxSize) return;
        const mark = picks.length;
        if (!addSpecies(picks, used, task.def) || !addTypes(picks, used, task.def) || !activeNow(picks, task.def)) {
            rollback(picks, mark, used);
        }
    };

    const usedOf = (picks: readonly Pick[]): Set<string> => {
        const used = new Set<string>();
        for (let i = 0; i < picks.length; i++) {
            const uid = picks[i]?.uid;
            if (uid) used.add(uid);
        }
        return used;
    };

    const localSearch = (start: Pick[]): Pick[] => {
        let current = start.slice();
        for (let pass = 0; pass < LOCAL_PASSES; pass++) {
            if (evals >= MAX_EVALS) break;
            let bestPicks = current;
            const baseMicro = evalMicro(current);
            if (baseMicro === null) break;
            let bestLocal = metricsOf(current, baseMicro, original);
            const used = usedOf(current);
            for (let slot = 0; slot < current.length; slot++) {
                const slotUid = current[slot]?.uid ?? '';
                if (pinned.has(slotUid)) continue;
                for (let a = 0; a < pruned.length; a++) {
                    const arch = pruned[a];
                    if (!arch) continue;
                    const inst = takeInstance(arch, used);
                    if (!inst || inst.uid === current[slot]?.uid) continue;
                    const next = current.slice();
                    next[slot] = toPick(arch, inst);
                    const micro = evalMicro(next);
                    if (micro === null) continue;
                    const scored = metricsOf(next, micro, original);
                    if (betterMetrics(scored, bestLocal)) {
                        bestLocal = scored;
                        bestPicks = next;
                    }
                }
            }
            if (current.length < maxSize) {
                for (let a = 0; a < pruned.length; a++) {
                    const arch = pruned[a];
                    if (!arch) continue;
                    const inst = takeInstance(arch, used);
                    if (!inst) continue;
                    const next = current.concat(toPick(arch, inst));
                    const micro = evalMicro(next);
                    if (micro === null) continue;
                    const scored = metricsOf(next, micro, original);
                    if (betterMetrics(scored, bestLocal)) {
                        bestLocal = scored;
                        bestPicks = next;
                    }
                }
            }
            if (bestPicks === current) break;
            current = bestPicks;
        }
        return current;
    };

    const pruneExtras = (start: Pick[]): Pick[] => {
        const picks = start.slice();
        for (let guard = 0; guard < maxSize; guard++) {
            const base = evalMicro(picks);
            if (base === null) break;
            let victim = -1;
            let victimPower = Infinity;
            let victimUid = '';
            for (let i = 0; i < picks.length; i++) {
                const pick = picks[i];
                if (!pick || original.has(pick.uid)) continue;
                const without = picks.slice();
                without.splice(i, 1);
                const micro = without.length === 0 ? null : evalMicro(without);
                if (micro === null || micro < base) continue;
                if (pick.combatPower < victimPower || (pick.combatPower === victimPower && pick.uid < victimUid)) {
                    victim = i;
                    victimPower = pick.combatPower;
                    victimUid = pick.uid;
                }
            }
            if (victim < 0) break;
            picks.splice(victim, 1);
        }
        return picks;
    };

    const reinsert = (start: Pick[]): Pick[] => {
        let picks = start.slice();
        for (let i = 0; i < originalPicks.length; i++) {
            const orig = originalPicks[i];
            if (!orig || picks.some((pick) => pick.uid === orig.uid)) continue;
            if (picks.length >= maxSize) break;
            const next = picks.concat(orig);
            const micro = evalMicro(next);
            const currentMicro = evalMicro(picks);
            if (micro === null || currentMicro === null) break;
            if (betterMetrics(metricsOf(next, micro, original), metricsOf(picks, currentMicro, original))) {
                picks = next;
            }
        }
        return picks;
    };

    const finish = (picks: Pick[]): Pick[] => reinsert(pruneExtras(picks));

    const runOrder = (order: readonly Task[], seed: Pick[]): Pick[] => {
        const picks = seed.slice();
        const used = usedOf(picks);
        for (let i = 0; i < order.length; i++) {
            const task = order[i];
            if (task) tryComplete(picks, used, task);
        }
        return picks;
    };

    const byWeight = tasks.slice().sort(cmpWeight);
    const byEff = tasks.slice().sort(cmpEff);
    const orders: Task[][] = [byWeight, byEff];
    const stride = Math.max(1, Math.floor(byWeight.length / 6));
    for (let i = 1; i <= 6; i++) orders.push(rotate(byWeight, i * stride));

    const realOf = (picks: readonly Pick[]): number => {
        const members: TeamSynergyMember[] = [];
        for (let i = 0; i < picks.length; i++) {
            const pick = picks[i];
            if (!pick) continue;
            members.push({ name: pick.name, type: pick.type, secondaryType: pick.secondaryType });
        }
        return scoreSynergyBonuses(aggregateSynergyEffects(members, game), input.objective);
    };

    let champ = originalPicks.slice();
    let champReal = realOf(champ);

    const adopt = (picks: readonly Pick[]): void => {
        if (!uniquePicks(picks) || picks.length === 0 || picks.length > maxSize || !keepsPinned(picks, pinned)) return;
        const real = realOf(picks);
        if (real < champReal - 1e-9) return;
        const micro = evalMicro(picks);
        if (micro === null) return;
        const metrics = metricsOf(picks, micro, original);
        const champMetrics = metricsOf(champ, evalMicro(champ) ?? 0, original);
        if (real > champReal + 1e-9 || (Math.abs(real - champReal) <= 1e-9 && betterMetrics(metrics, champMetrics))) {
            champ = picks.slice();
            champReal = real;
        }
    };

    const stepFrom = (base: Pick[]): void => {
        const changeBase = new Set<string>();
        for (let i = 0; i < base.length; i++) {
            const uid = base[i]?.uid;
            if (uid) changeBase.add(uid);
        }
        const step = searchAdjust({
            base,
            tasks,
            arches,
            pruned,
            maxSize,
            original,
            currentMicro: evalMicro(base) ?? 0,
            evalMicro,
            activeNow,
            pinned,
            changeBase,
            realOf,
        });
        if (step) adopt(step);
    };

    const triedNames = (picks: readonly Pick[]): string[] => {
        const names: string[] = [];
        const seen = new Set<string>();
        for (let i = 0; i < picks.length; i++) {
            const name = picks[i]?.name;
            if (!name || seen.has(name)) continue;
            seen.add(name);
            names.push(name);
            if (names.length >= 10) break;
        }
        return names;
    };

    let cursor = 0;
    let finalized = false;

    const closeChamp = (): void => {
        for (let guard = 0; guard < 3; guard++) {
            evals = 0;
            const before = champReal;
            for (let i = 0; i < orders.length; i++) {
                const order = orders[i];
                if (!order) continue;
                adopt(finish(runOrder(order, champ.slice())));
            }
            evals = 0;
            stepFrom(champ);
            if (champReal <= before + 1e-9) break;
        }
    };

    const next = (): SynergyRoundInfo | null => {
        if (rounds <= 0 || cursor >= rounds) return null;
        cursor += 1;
        evals = 0;
        const order = orders[(cursor - 1) % orders.length] ?? byWeight;
        const seed = cursor > rounds - orders.length
            ? champ
            : cursor % 3 === 0
                ? []
                : cursor % 3 === 1
                    ? originalPicks
                    : champ;
        const picks = finish(localSearch(runOrder(order, seed.slice())));
        adopt(picks);
        evals = 0;
        stepFrom(champ);
        return {
            round: cursor,
            roundCount: rounds,
            bestScore: champReal,
            names: triedNames(picks.length > 0 ? picks : champ),
        };
    };

    const result = (): SynergyOptimizeResult => {
        if (!finalized) {
            finalized = true;
            if (rounds >= SYNERGY_DEEP_ROUNDS) closeChamp();
        }
        const bestProposal = toProposal(champ, originalPicks, originalUids, original, game, input.objective);
        const adjustPicks = searchAdjust({
            base: originalPicks,
            tasks,
            arches,
            pruned,
            maxSize,
            original,
            currentMicro: evalMicro(originalPicks) ?? 0,
            evalMicro,
            activeNow,
            pinned,
            changeBase: original,
            realOf,
        });
        let adjust: SynergyRosterProposal | null = null;
        if (adjustPicks && !sameUidSet(adjustPicks.map((pick) => pick.uid), bestProposal.uids)) {
            const proposal = toProposal(adjustPicks, originalPicks, originalUids, original, game, input.objective);
            if (proposal.score > proposal.currentScore) adjust = proposal;
        }
        return { best: bestProposal, adjust };
    };

    return { roundCount: rounds, next, result };
}

function searchAdjust(args: {
    base: Pick[];
    tasks: Task[];
    arches: Arch[];
    pruned: Arch[];
    maxSize: number;
    original: Set<string>;
    currentMicro: number;
    evalMicro: (picks: readonly Pick[]) => number | null;
    activeNow: (picks: readonly Pick[], def: TeamSynergyDef) => boolean;
    pinned: ReadonlySet<string>;
    /** Counts the 1–2 change cap against this set. Defaults to the original team. */
    changeBase?: Set<string>;
    realOf?: (picks: readonly Pick[]) => number;
}): Pick[] | null {
    const { base, pruned, maxSize, original, currentMicro, evalMicro, pinned, realOf } = args;
    const limit = args.changeBase ?? original;
    const shortlist: { picks: Pick[]; micro: number; changes: number; metrics: Metrics }[] = [];

    const consider = (picks: Pick[]): void => {
        if (!uniquePicks(picks) || picks.length === 0 || picks.length > maxSize || !keepsPinned(picks, pinned)) return;
        const changes = changeCount(picks, limit);
        if (changes < 1 || changes > 2) return;
        const micro = evalMicro(picks);
        if (micro === null || micro <= currentMicro) return;
        const scored = metricsOf(picks, micro, original);
        const cand = { picks: picks.slice(), micro, changes, metrics: scored };
        let placed = false;
        for (let i = 0; i < shortlist.length; i++) {
            const current = shortlist[i];
            if (!current) continue;
            const better = cand.micro > current.micro
                || (cand.micro === current.micro && cand.changes < current.changes)
                || (cand.micro === current.micro && cand.changes === current.changes && betterMetrics(scored, current.metrics));
            if (!better) continue;
            shortlist.splice(i, 0, cand);
            placed = true;
            break;
        }
        if (!placed && shortlist.length < 8) shortlist.push(cand);
        if (shortlist.length > 8) shortlist.length = 8;
    };

    const freeSlots: number[] = [];
    for (let i = 0; i < base.length; i++) {
        const uid = base[i]?.uid ?? '';
        if (!pinned.has(uid)) freeSlots.push(i);
    }

    const place = (incoming: Pick[]): void => {
        if (incoming.length === 0 || incoming.length > 2) return;
        if (base.length + incoming.length <= maxSize) consider(base.concat(incoming));
        const combos = slotCombos(freeSlots.length, incoming.length);
        for (let c = 0; c < combos.length; c++) {
            const combo = combos[c];
            if (!combo) continue;
            const next = base.slice();
            let ok = true;
            for (let k = 0; k < combo.length; k++) {
                const slot = freeSlots[combo[k] ?? -1];
                const pick = incoming[k];
                if (slot === undefined || !pick) {
                    ok = false;
                    break;
                }
                next[slot] = pick;
            }
            if (ok) consider(next);
        }
    };

    const used = new Set(base.map((pick) => pick.uid));
    const marginal: { arch: Arch; micro: number }[] = [];
    for (let a = 0; a < pruned.length; a++) {
        const arch = pruned[a];
        if (!arch) continue;
        const inst = takeInstance(arch, used);
        if (!inst) continue;
        const pick = toPick(arch, inst);
        let bestMicro = currentMicro;
        if (base.length < maxSize) {
            const micro = evalMicro(base.concat(pick));
            if (micro !== null && micro > bestMicro) bestMicro = micro;
            consider(base.concat(pick));
        }
        for (let s = 0; s < freeSlots.length; s++) {
            const slot = freeSlots[s];
            if (slot === undefined) continue;
            const next = base.slice();
            next[slot] = pick;
            const micro = evalMicro(next);
            if (micro !== null && micro > bestMicro) bestMicro = micro;
            consider(next);
        }
        marginal.push({ arch, micro: bestMicro });
    }
    marginal.sort((a, b) => b.micro - a.micro || b.arch.affinity - a.arch.affinity || (a.arch.key < b.arch.key ? -1 : 1));
    const top = marginal.slice(0, 12);

    for (let i = 0; i < top.length; i++) {
        for (let j = i; j < top.length; j++) {
            const archA = top[i]?.arch;
            const archB = top[j]?.arch;
            if (!archA || !archB) continue;
            const gate = new Set(used);
            const instA = takeInstance(archA, gate);
            if (!instA) continue;
            gate.add(instA.uid);
            const instB = takeInstance(archB, gate);
            if (!instB) continue;
            place([toPick(archA, instA), toPick(archB, instB)]);
        }
    }

    explicitCompletions(args, place);
    if (!realOf) return shortlist[0]?.picks ?? null;
    let bestPicks: Pick[] | null = null;
    let bestReal = realOf(base);
    for (let i = 0; i < shortlist.length; i++) {
        const cand = shortlist[i];
        if (!cand) continue;
        const real = realOf(cand.picks);
        if (real <= bestReal + 1e-9) continue;
        bestReal = real;
        bestPicks = cand.picks;
    }
    return bestPicks;
}

function explicitCompletions(
    args: {
        base: Pick[];
        tasks: Task[];
        arches: Arch[];
        evalMicro: (picks: readonly Pick[]) => number | null;
        activeNow: (picks: readonly Pick[], def: TeamSynergyDef) => boolean;
    },
    place: (incoming: Pick[]) => void,
): void {
    const { base, tasks, arches, activeNow } = args;
    const used = new Set(base.map((pick) => pick.uid));
    for (let t = 0; t < tasks.length; t++) {
        const task = tasks[t];
        if (!task || activeNow(base, task.def)) continue;
        const rule = task.def.requiredSpecies;
        if (rule?.species?.length) {
            const minCount = Math.max(1, Math.floor(Number(rule.minCount) || 1));
            if (minCount >= rule.species.length) {
                const missing = rule.species.filter((name) => !base.some((pick) => pick.name === name));
                if (missing.length >= 1 && missing.length <= 2) {
                    const incoming: Pick[] = [];
                    const gate = new Set(used);
                    let ok = true;
                    for (let i = 0; i < missing.length; i++) {
                        const name = missing[i];
                        const arch = arches.find((item) => item.name === name);
                        const inst = arch ? takeInstance(arch, gate) : null;
                        if (!arch || !inst) {
                            ok = false;
                            break;
                        }
                        gate.add(inst.uid);
                        incoming.push(toPick(arch, inst));
                    }
                    if (ok) place(incoming);
                }
            } else {
                const matched = base.filter((pick) => rule.species.includes(pick.name)).length;
                const need = minCount - matched;
                const candidates: Pick[] = [];
                const gate = new Set(used);
                for (let i = 0; i < arches.length && candidates.length < 8; i++) {
                    const arch = arches[i];
                    if (!arch || !rule.species.includes(arch.name)) continue;
                    const inst = takeInstance(arch, gate);
                    if (!inst) continue;
                    gate.add(inst.uid);
                    candidates.push(toPick(arch, inst));
                }
                if (need === 1) {
                    for (let i = 0; i < candidates.length; i++) {
                        const pick = candidates[i];
                        if (pick) place([pick]);
                    }
                } else if (need === 2) {
                    for (let i = 0; i < candidates.length; i++) {
                        for (let j = i; j < candidates.length; j++) {
                            const first = candidates[i];
                            const second = candidates[j];
                            if (!first || !second || first.uid === second.uid) continue;
                            place([first, second]);
                        }
                    }
                }
            }
        }
        const gaps = typeGapMap(task.def, base);
        let slotNeed = 0;
        for (const gap of gaps.values()) slotNeed += gap;
        if (slotNeed < 1 || slotNeed > 2) continue;
        if (rule?.species?.length) {
            const minCount = Math.max(1, Math.floor(Number(rule.minCount) || 1));
            const satisfied = minCount >= rule.species.length
                ? rule.species.every((name) => base.some((pick) => pick.name === name))
                : base.filter((pick) => rule.species.includes(pick.name)).length >= minCount;
            if (!satisfied) continue;
        }
        const gapTypes = [...gaps.keys()];
        const coversAll = (arch: Arch): boolean => gapTypes.every((type) => archCovers(arch, type, task.def));
        const singles: Pick[] = [];
        const gate = new Set(used);
        for (let i = 0; i < arches.length && singles.length < 8; i++) {
            const arch = arches[i];
            if (!arch || !coversAll(arch)) continue;
            const inst = takeInstance(arch, gate);
            if (!inst) continue;
            gate.add(inst.uid);
            singles.push(toPick(arch, inst));
        }
        if (slotNeed === 1) {
            for (let i = 0; i < singles.length; i++) {
                const pick = singles[i];
                if (pick) place([pick]);
            }
        } else {
            for (let i = 0; i < singles.length; i++) {
                for (let j = i; j < singles.length; j++) {
                    const first = singles[i];
                    const second = singles[j];
                    if (!first || !second || first.uid === second.uid) continue;
                    place([first, second]);
                }
            }
        }
    }
}

function speciesMet(def: TeamSynergyDef, nameCounts: Map<string, number>): boolean {
    const rule = def.requiredSpecies;
    if (!rule?.species?.length) return true;
    const minCount = Math.max(1, Math.floor(Number(rule.minCount) || 1));
    if (minCount >= rule.species.length) {
        for (let i = 0; i < rule.species.length; i++) {
            const name = rule.species[i];
            if (!name || (nameCounts.get(name) || 0) < 1) return false;
        }
        return true;
    }
    let matched = 0;
    for (let i = 0; i < rule.species.length; i++) {
        const name = rule.species[i];
        if (name) matched += nameCounts.get(name) || 0;
    }
    return matched >= minCount;
}

function typesMet(def: TeamSynergyDef, counts: Record<string, number>): boolean {
    const types = def.types;
    const minCount = def.min_count;
    if (!types?.length || !minCount) return true;
    if (def.all_required) {
        for (let i = 0; i < types.length; i++) {
            const type = types[i];
            if (!type || (counts[type] || 0) < minCount) return false;
        }
        return true;
    }
    for (let i = 0; i < types.length; i++) {
        const type = types[i];
        if (type && (counts[type] || 0) >= minCount) return true;
    }
    return false;
}

function clearCounts(counts: Record<string, number>, seen: string[]): void {
    for (let i = 0; i < seen.length; i++) counts[seen[i]!] = 0;
    seen.length = 0;
}

function bumpCount(counts: Record<string, number>, seen: string[], type: string): void {
    const prev = counts[type] || 0;
    if (prev === 0) seen.push(type);
    counts[type] = prev + 1;
}

function scorePicks(
    picks: readonly Pick[],
    tasks: readonly Task[],
    nameCounts: Map<string, number>,
    typeCounts: Record<string, number>,
    typeSeen: string[],
    regionalCounts: Record<string, number>,
    regionalSeen: string[],
): number {
    nameCounts.clear();
    clearCounts(typeCounts, typeSeen);
    for (let i = 0; i < picks.length; i++) {
        const pick = picks[i];
        if (!pick) continue;
        if (pick.type) bumpCount(typeCounts, typeSeen, pick.type);
        if (pick.secondaryType) bumpCount(typeCounts, typeSeen, pick.secondaryType);
        nameCounts.set(pick.name, (nameCounts.get(pick.name) || 0) + 1);
    }
    let sum = 0;
    for (let i = 0; i < tasks.length; i++) {
        const task = tasks[i];
        if (!task || !speciesMet(task.def, nameCounts)) continue;
        if (task.def.regionalTypesOnly === true) {
            clearCounts(regionalCounts, regionalSeen);
            for (let p = 0; p < picks.length; p++) {
                const pick = picks[p];
                if (!pick || pick.arch.native !== task.def.regionId) continue;
                if (pick.type) bumpCount(regionalCounts, regionalSeen, pick.type);
                if (pick.secondaryType) bumpCount(regionalCounts, regionalSeen, pick.secondaryType);
            }
            if (!typesMet(task.def, regionalCounts)) continue;
        } else if (!typesMet(task.def, typeCounts)) {
            continue;
        }
        sum += task.weight;
    }
    return sum;
}

function sameUidSet(a: readonly string[], b: readonly string[]): boolean {
    if (a.length !== b.length) return false;
    const set = new Set(b);
    for (let i = 0; i < a.length; i++) {
        if (!set.has(a[i] ?? '')) return false;
    }
    return true;
}

function toProposal(
    picks: readonly Pick[],
    originalPicks: readonly Pick[],
    originalUids: readonly string[],
    original: Set<string>,
    game: GameRuntime | null,
    objective: SynergyObjective,
): SynergyRosterProposal {
    const uids = orderTeam(originalUids, picks);
    const byUid = new Map<string, Pick>();
    for (let i = 0; i < picks.length; i++) {
        const pick = picks[i];
        if (pick) byUid.set(pick.uid, pick);
    }
    const orderedMembers: TeamSynergyMember[] = [];
    for (let i = 0; i < uids.length; i++) {
        const pick = byUid.get(uids[i] ?? '');
        if (!pick) continue;
        orderedMembers.push({ name: pick.name, type: pick.type, secondaryType: pick.secondaryType });
    }
    const currentMembers: TeamSynergyMember[] = originalPicks.map((pick) => ({
        name: pick.name,
        type: pick.type,
        secondaryType: pick.secondaryType,
    }));
    const nextBonuses = aggregateSynergyEffects(orderedMembers, game);
    const prevBonuses = aggregateSynergyEffects(currentMembers, game);
    const nextIds = getActiveSynergyEntries(orderedMembers, game).map((entry) => entry.id).sort();
    const prevIds = new Set(getActiveSynergyEntries(currentMembers, game).map((entry) => entry.id));
    const gainedSynergyIds = nextIds.filter((id) => !prevIds.has(id));
    const lostSynergyIds = [...prevIds].filter((id) => !nextIds.includes(id)).sort();
    const chosen = new Set(uids);
    const removed: SynergyRosterMove[] = [];
    for (let i = 0; i < originalPicks.length; i++) {
        const pick = originalPicks[i];
        if (pick && !chosen.has(pick.uid)) removed.push({ uid: pick.uid, name: pick.name });
    }
    const added: SynergyRosterMove[] = [];
    for (let i = 0; i < uids.length; i++) {
        const uid = uids[i] ?? '';
        if (original.has(uid)) continue;
        const pick = byUid.get(uid);
        if (pick) added.push({ uid: pick.uid, name: pick.name });
    }
    const statDelta: Partial<Record<SynergyObjectiveKey, number>> = {};
    for (let i = 0; i < SYNERGY_OBJECTIVE_KEYS.length; i++) {
        const key = SYNERGY_OBJECTIVE_KEYS[i];
        if (!key) continue;
        const delta = nextBonuses[key] - prevBonuses[key];
        if (Math.abs(delta) > 1e-9) statDelta[key] = delta;
    }
    const score = scoreSynergyBonuses(nextBonuses, objective);
    const currentScore = scoreSynergyBonuses(prevBonuses, objective);
    return {
        uids,
        score,
        currentScore,
        changeCount: Math.max(added.length, removed.length),
        added,
        removed,
        gainedSynergyIds,
        lostSynergyIds,
        statDelta,
    };
}

function affinityOf(arch: Arch, tasks: readonly Task[]): number {
    let score = 0;
    for (let i = 0; i < tasks.length; i++) {
        const task = tasks[i];
        if (!task) continue;
        const species = task.def.requiredSpecies?.species;
        if (species?.includes(arch.name)) score += task.weight;
        const types = task.def.types;
        if (!types?.length) continue;
        for (let t = 0; t < types.length; t++) {
            const type = types[t];
            if (type && archCovers(arch, type, task.def)) {
                score += task.weight * 0.5;
                break;
            }
        }
    }
    return score;
}

function ownersOf(arches: readonly Arch[], type: string, def: TeamSynergyDef): number {
    let count = 0;
    for (let i = 0; i < arches.length; i++) {
        const arch = arches[i];
        if (!arch || !archCovers(arch, type, def)) continue;
        count += arch.instances.length;
    }
    return count;
}

function canEverSatisfy(def: TeamSynergyDef, arches: readonly Arch[]): boolean {
    const rule = def.requiredSpecies;
    if (rule?.species?.length) {
        const minCount = Math.max(1, Math.floor(Number(rule.minCount) || 1));
        if (minCount >= rule.species.length) {
            for (let i = 0; i < rule.species.length; i++) {
                const name = rule.species[i];
                if (!arches.some((arch) => arch.name === name && arch.instances.length > 0)) return false;
            }
        } else {
            let copies = 0;
            for (let i = 0; i < arches.length; i++) {
                const arch = arches[i];
                if (arch && rule.species.includes(arch.name)) copies += arch.instances.length;
            }
            if (copies < minCount) return false;
        }
    }
    if (def.types?.length && def.min_count) {
        if (def.all_required) {
            for (let i = 0; i < def.types.length; i++) {
                const type = def.types[i];
                if (!type || ownersOf(arches, type, def) < def.min_count) return false;
            }
        } else if (!def.types.some((type) => ownersOf(arches, type, def) >= (def.min_count ?? 0))) {
            return false;
        }
    }
    return true;
}

function buildTasks(arches: readonly Arch[], game: GameRuntime | null, keys: ReadonlySet<string> | null): Task[] {
    const tasks: Task[] = [];
    const synergies = TEAM_SYNERGIES as Record<string, TeamSynergyDef>;
    const ids = Object.keys(synergies).sort();
    for (let i = 0; i < ids.length; i++) {
        const id = ids[i];
        if (!id) continue;
        const def = synergies[id];
        if (!def) continue;
        if (!isSynergyRegionUnlocked(game, def.regionId)) continue;
        const weight = effectWeight(def, keys);
        if (weight <= 0) continue;
        if (!canEverSatisfy(def, arches)) continue;
        tasks.push({ id, def, weight, slots: estimateSlots(def) });
    }
    return tasks;
}

function pruneArchetypes(arches: readonly Arch[], tasks: readonly Task[]): Arch[] {
    const must = new Set<string>();
    for (let i = 0; i < tasks.length; i++) {
        const species = tasks[i]?.def.requiredSpecies?.species;
        if (!species) continue;
        for (let s = 0; s < species.length; s++) {
            const name = species[s];
            if (name) must.add(name);
        }
    }
    const required: Arch[] = [];
    const rest: Arch[] = [];
    for (let i = 0; i < arches.length; i++) {
        const arch = arches[i];
        if (!arch) continue;
        if (must.has(arch.name)) required.push(arch);
        else if (arch.affinity > 0) rest.push(arch);
    }
    required.sort((a, b) => (a.key < b.key ? -1 : 1));
    rest.sort((a, b) => {
        if (b.affinity !== a.affinity) return b.affinity - a.affinity;
        const ap = a.instances[0]?.combatPower ?? 0;
        const bp = b.instances[0]?.combatPower ?? 0;
        if (bp !== ap) return bp - ap;
        return a.key < b.key ? -1 : 1;
    });
    return required.concat(rest).slice(0, Math.max(PRUNED_CAP, required.length));
}
