<script lang="ts">
  import { useGameLanguageTick } from '../lib/useGameLanguageTick.svelte.ts';
  import type { GameRuntime } from '../types/game.js';
  import SynergyListContent from './SynergyListContent.svelte';

  const { trackGameLanguage } = useGameLanguageTick();

  function getGame(): GameRuntime | null {
    return (globalThis as { game?: GameRuntime }).game ?? null;
  }

  function t(key: string, fallback: string): string {
    const g = getGame();
    if (!g?.t) return fallback;
    const got = g.t(key);
    return got && got !== key ? got : fallback;
  }

  let titleLabel = $derived.by(() => {
    trackGameLanguage();
    return t('modal.synergyGuideTitle', 'Guide des Synergies');
  });
</script>

<div class="stats-content" data-action="stopPropagation" data-action-stop>
  <div class="stats-header">
    <h2 id="synergyGuideTitleLabel">{titleLabel}</h2>
    <button class="stats-close" data-action="closeSynergyListModal">&#10005;</button>
  </div>
  <SynergyListContent />
</div>
