<script lang="ts">
  import { onDestroy, onMount } from 'svelte';
  import { team } from '../stores/team.svelte.ts';
  import { isModalOpen } from '../stores/ui.svelte.ts';
  import { game } from '../../gameManager.js';
  import type { GameRuntime } from '../types/game.js';
  import { GameEventType as Evt, type GameEvent } from '../bus/events.js';
  import { useFacadeSubscription } from '../lib/useFacadeSubscription.ts';
  import { useGameLanguageTick } from '../lib/useGameLanguageTick.svelte.ts';
  import { getMaxTeamSize } from '../lib/playerCombatRoster.ts';
  import {
    buildSynergyCards,
    buildSynergyRegionTabs,
    defaultSynergyRegionTab,
    regionLabel,
    synergyDisplayName,
    type SynergyCardView,
  } from '../lib/synergyListLogic.js';
  import {
    collectSynergyCandidates,
    objectiveFromStatFilters,
    openSynergyDeepSearch,
    optimizeSynergyRoster,
    synergyRosterSearchKey,
    synergySlotSubstitutes,
    SYNERGY_DEEP_ROUNDS,
    SYNERGY_DRAW_RARITIES,
    SYNERGY_OBJECTIVE_KEYS,
    type SynergyObjectiveKey,
    type SynergyOptimizeResult,
    type SynergyRosterProposal,
  } from '../lib/synergyOptimizer.ts';
  import { SYNERGY_REGION_ORDER } from '../../constants/balance/teamSynergies/types.ts';
  import { getUnlockedSynergyRegionIds } from '../lib/synergyRegionUnlock.ts';
  import { showGameTooltip, hideGameTooltip, touchTooltipHandlers } from '../ui/scheduleTooltipHelpers.ts';
  import { getPokemonSpriteUrl } from '../lib/cardSprites.ts';
  import { getPokemonSpritePath } from '../ui/utils.ts';
  import { localizePokemonName } from '../../constants/pokemonNameI18n.ts';

  const POOL_STORAGE_KEY = 'poketime:synergyOptimizerPools';
  const KEY_TO_FILTER: Record<SynergyObjectiveKey, string> = {
    max_hp_mult: 'hp',
    attack_mult: 'atk',
    spattack_mult: 'spatk',
    defense_mult: 'def',
    spdefense_mult: 'spdef',
    speed_mult: 'spd',
    heal_mult: 'heal',
    exp_mult: 'exp',
    pokedollars_mult: 'money',
  };

  interface OptimizerPillView {
    key: SynergyObjectiveKey;
    cls: string;
    label: string;
    valueText: string;
    loss: boolean;
    aside: boolean;
  }

  interface OptimizerSpriteView {
    uid: string;
    alt: string;
    src: string;
    leaving: boolean;
  }

  interface OptimizerCardView {
    title: string;
    ariaLabel: string;
    hero: string;
    heroKind: 'delta' | 'lock' | 'wait';
    jump: string;
    pills: OptimizerPillView[];
    gainedText: string;
    gainedExtra: number;
    lostText: string;
    lostExtra: number;
    sprites: OptimizerSpriteView[];
    spriteExtra: number;
    tooltipTitle: string;
    tooltipBody: string;
    disabled: boolean;
    uids: readonly string[];
  }

  const SPRITE_CAP = 6;
  const SYNERGY_NAME_CAP = 2;

  function readAllowedRarities(value: unknown): string[] {
    if (!Array.isArray(value)) return SYNERGY_DRAW_RARITIES.slice();
    const allowed: string[] = [];
    for (let i = 0; i < value.length; i++) {
      const id = value[i];
      if (typeof id === 'string' && (SYNERGY_DRAW_RARITIES as readonly string[]).includes(id) && !allowed.includes(id)) {
        allowed.push(id);
      }
    }
    return allowed;
  }

  function readAllowedRegions(value: unknown): string[] {
    if (!Array.isArray(value)) return SYNERGY_REGION_ORDER.slice();
    const allowed: string[] = [];
    for (let i = 0; i < value.length; i++) {
      const id = value[i];
      if (typeof id === 'string' && (SYNERGY_REGION_ORDER as readonly string[]).includes(id) && !allowed.includes(id)) {
        allowed.push(id);
      }
    }
    return allowed;
  }

  function readOptimizerPools(): { includeStorage: boolean; includePension: boolean; allowedRarities: string[]; allowedRegions: string[] } {
    const fallback = {
      includeStorage: true,
      includePension: true,
      allowedRarities: SYNERGY_DRAW_RARITIES.slice(),
      allowedRegions: SYNERGY_REGION_ORDER.slice(),
    };
    if (typeof localStorage === 'undefined') return fallback;
    try {
      const raw = localStorage.getItem(POOL_STORAGE_KEY);
      if (!raw) return fallback;
      const parsed: unknown = JSON.parse(raw);
      if (!parsed || typeof parsed !== 'object') return fallback;
      const record = parsed as { includeStorage?: unknown; includePension?: unknown; allowedRarities?: unknown; allowedRegions?: unknown };
      if (typeof record.includeStorage !== 'boolean' || typeof record.includePension !== 'boolean') return fallback;
      return {
        includeStorage: record.includeStorage,
        includePension: record.includePension,
        allowedRarities: readAllowedRarities(record.allowedRarities),
        allowedRegions: readAllowedRegions(record.allowedRegions),
      };
    } catch {
      return fallback;
    }
  }

  function writeOptimizerPools(
    storageOn: boolean,
    pensionOn: boolean,
    rarities: readonly string[],
    regions: readonly string[],
  ): void {
    if (typeof localStorage === 'undefined') return;
    try {
      localStorage.setItem(POOL_STORAGE_KEY, JSON.stringify({
        includeStorage: storageOn,
        includePension: pensionOn,
        allowedRarities: rarities,
        allowedRegions: regions,
      }));
    } catch {
      // Private browsing can reject the write. The toggles still work for this visit.
    }
  }

  const { trackGameLanguage } = useGameLanguageTick();
  const initialPools = readOptimizerPools();

  let selectedRegion = $state(
    defaultSynergyRegionTab(game as GameRuntime | null),
  );
  let selectedStats = $state<string[]>([]);
  let includeStorage = $state(initialPools.includeStorage);
  let includePension = $state(initialPools.includePension);
  let allowedRarities = $state<string[]>(initialPools.allowedRarities);
  let allowedRegions = $state<string[]>(initialPools.allowedRegions);
  let optimizerUnlocked = $state(optimizerIsUnlocked());
  let userToggledOthers = $state<boolean | null>(null);
  interface ReelSpriteView {
    src: string;
    alt: string;
  }

  interface SearchSnapshot {
    key: string;
    members: ReturnType<typeof collectSynergyCandidates>;
    objective: ReturnType<typeof objectiveFromStatFilters>;
    includeStorage: boolean;
    includePension: boolean;
    allowedRarities: string[];
    allowedRegions: string[];
    maxTeamSize: number;
    pinnedUids: string[];
    game: GameRuntime;
  }

  let optimizeResult = $state.raw<SynergyOptimizeResult | null>(null);
  let adjustProposal = $state.raw<SynergyRosterProposal | null>(null);
  let undoReady = $state(false);
  let pinnedUids = $state<string[]>([]);
  let deepRunning = $state(false);
  let deepRound = $state(0);
  let deepRoundCount = $state(SYNERGY_DEEP_ROUNDS);
  let deepBestScore = $state(0);
  let deepNames = $state<string[]>([]);
  let searchTimer: ReturnType<typeof setTimeout> | null = null;
  let deepTimer: ReturnType<typeof setTimeout> | null = null;
  let searchSeq = 0;
  let deepSeq = 0;
  let lastSearchKey = '';
  let pendingKey = '';

  const STAT_FILTERS = [
    { id: 'hp', labelFr: 'PV', labelEn: 'HP', cls: 'hp', tooltipFr: 'Points de Vie', tooltipEn: 'Health Points' },
    { id: 'atk', labelFr: 'ATK', labelEn: 'ATK', cls: 'atk', tooltipFr: 'Attaque', tooltipEn: 'Attack' },
    { id: 'spatk', labelFr: 'ATK SP', labelEn: 'ATK SP', cls: 'spatk', tooltipFr: 'Attaque Spéciale', tooltipEn: 'Special Attack' },
    { id: 'def', labelFr: 'DEF', labelEn: 'DEF', cls: 'def', tooltipFr: 'Défense', tooltipEn: 'Defense' },
    { id: 'spdef', labelFr: 'DEF SP', labelEn: 'DEF SP', cls: 'spdef', tooltipFr: 'Défense Spéciale', tooltipEn: 'Special Defense' },
    { id: 'spd', labelFr: 'SPD', labelEn: 'SPD', cls: 'spd', tooltipFr: 'Vitesse', tooltipEn: 'Speed' },
    { id: 'heal', labelFr: 'SOINS', labelEn: 'HEAL', cls: 'heal', tooltipFr: 'Soins', tooltipEn: 'Healing' },
    { id: 'exp', labelFr: 'XP', labelEn: 'XP', cls: 'exp', tooltipFr: 'Expérience', tooltipEn: 'Experience' },
    { id: 'money', labelFr: '$', labelEn: '$', cls: 'money', isMoney: true, tooltipFr: 'Pokédollars', tooltipEn: 'Pokédollars' },
  ];

  onMount(() => {
    function handleSelectRegion(e: Event) {
      const customEvent = e as CustomEvent<string>;
      if (customEvent.detail) {
        selectedRegion = customEvent.detail;
        userToggledOthers = null;
      }
    }
    window.addEventListener('select-synergy-region', handleSelectRegion);
    return () => {
      window.removeEventListener('select-synergy-region', handleSelectRegion);
    };
  });

  let regionTabs = $derived.by(() => {
    trackGameLanguage();
    const gm = game as GameRuntime | null;
    if (!gm) return [];
    return buildSynergyRegionTabs(gm, team.playerTeam);
  });

  let allRegionCards = $derived.by((): SynergyCardView[] => {
    trackGameLanguage();
    const gm = game as GameRuntime | null;
    if (!gm) return [];
    void selectedRegion;
    return buildSynergyCards(gm, team.playerTeam, { regionId: selectedRegion });
  });

  function selectedBonusVal(card: SynergyCardView): number {
    if (selectedStats.length === 0) return card.totalBonusVal;
    let sum = 0;
    for (let i = 0; i < card.bonuses.length; i++) {
      const bonus = card.bonuses[i];
      if (bonus && selectedStats.includes(bonus.cls)) sum += bonus.val;
    }
    return sum;
  }

  let effectiveShowOthers = $derived.by(() => {
    if (selectedStats.length > 0) return true;
    if (userToggledOthers !== null) return userToggledOthers;
    return activeCards.length === 0 && almostCards.length === 0;
  });

  let displayedCards = $derived.by(() => {
    if (selectedStats.length === 0) return allRegionCards;
    return allRegionCards.filter((card) => card.bonuses.some((bonus) => selectedStats.includes(bonus.cls)));
  });

  let activeCards = $derived.by(() => {
    return displayedCards
      .filter((card) => card.isActive)
      .slice()
      .sort((a, b) => selectedBonusVal(b) - selectedBonusVal(a));
  });

  let almostCards = $derived.by(() => {
    return displayedCards
      .filter((card) => !card.isActive && card.isAlmost)
      .slice()
      .sort((a, b) => selectedBonusVal(b) - selectedBonusVal(a));
  });

  let otherCards = $derived.by(() => {
    const list = displayedCards.filter((card) => !card.isActive && !card.isAlmost);
    if (selectedStats.length > 0) {
      return [...list].sort((a, b) => selectedBonusVal(b) - selectedBonusVal(a));
    }
    return [...list].sort((a, b) => {
      if (a.missingCount !== b.missingCount) return a.missingCount - b.missingCount;
      return b.totalBonusVal - a.totalBonusVal;
    });
  });

  function cardHandlers(card: SynergyCardView) {
    return touchTooltipHandlers(() => ({
      title: card.tooltipTitle,
      body: card.tooltipDesc,
    }));
  }

  function gameLang(): string {
    const gm = game as GameRuntime | null;
    return (typeof gm?.normalizeLanguage === 'function' ? gm.normalizeLanguage(gm.language) : gm?.language) || 'fr';
  }

  function activeSectionLabel(): string {
    return gameLang() === 'fr' ? 'ACTIVES' : 'ACTIVE';
  }

  function almostSectionLabel(): string {
    return gameLang() === 'fr' ? 'PROCHES' : 'ALMOST';
  }

  function otherSectionLabel(): string {
    return gameLang() === 'fr' ? 'AUTRES' : 'OTHER';
  }

  function speciesIsMatched(card: SynergyCardView, speciesName: string): boolean {
    return card.speciesProgress?.matchedSpecies.includes(speciesName) ?? false;
  }

  function lockedTabTooltip(regionId: string): string {
    const gm = game as GameRuntime | null;
    const name = regionLabel(gm, regionId);
    const key = 'tooltip.synergyRegionLocked';
    const tpl = gm?.t?.(key);
    if (tpl && tpl !== key) return tpl.replace('{region}', name);
    return `Visit ${name} to unlock these synergies`;
  }

  function selectRegion(regionId: string, locked: boolean, e: MouseEvent) {
    if (locked) {
      const gm = game as GameRuntime | null;
      if (gm?.scheduleTooltip) {
        gm.scheduleTooltip(e, '', lockedTabTooltip(regionId));
      }
      return;
    }
    selectedRegion = regionId;
    userToggledOthers = null;
  }

  function tr(key: string, vars?: Record<string, string | number>): string {
    const gm = game as GameRuntime | null;
    if (!gm?.t) return key;
    return gm.t(key, vars);
  }

  function pctPoints(fraction: number): number {
    return Math.round(fraction * 100);
  }

  function statTag(key: SynergyObjectiveKey, lang: string): string {
    const filter = STAT_FILTERS.find((entry) => entry.id === KEY_TO_FILTER[key]);
    if (!filter) return key;
    return lang === 'fr' ? filter.labelFr : filter.labelEn;
  }

  function signedPoints(points: number): string {
    if (points > 0) return `+${points}`;
    if (points < 0) return `−${Math.abs(points)}`;
    return '0';
  }

  function keyForFilter(id: string): SynergyObjectiveKey | null {
    for (let i = 0; i < SYNERGY_OBJECTIVE_KEYS.length; i++) {
      const key = SYNERGY_OBJECTIVE_KEYS[i];
      if (key && KEY_TO_FILTER[key] === id) return key;
    }
    return null;
  }

  function buildPills(proposal: SynergyRosterProposal, lang: string): OptimizerPillView[] {
    const focusAll = selectedStats.length === 0;
    const chosen = new Set(selectedStats);
    const pills: OptimizerPillView[] = [];
    for (let i = 0; i < STAT_FILTERS.length; i++) {
      const filter = STAT_FILTERS[i];
      if (!filter) continue;
      const key = keyForFilter(filter.id);
      if (!key) continue;
      const delta = proposal.statDelta[key];
      if (delta == null || Math.abs(delta) < 1e-9) continue;
      const points = pctPoints(delta);
      if (points === 0) continue;
      pills.push({
        key,
        cls: filter.cls,
        label: lang === 'fr' ? filter.labelFr : filter.labelEn,
        valueText: signedPoints(points),
        loss: points < 0,
        aside: !focusAll && !chosen.has(filter.id),
      });
    }
    return pills;
  }

  function capNames(names: readonly string[]): { text: string; extra: number } {
    return {
      text: names.slice(0, SYNERGY_NAME_CAP).join(', '),
      extra: Math.max(0, names.length - SYNERGY_NAME_CAP),
    };
  }

  function buildSprites(proposal: SynergyRosterProposal, lang: string): { sprites: OptimizerSpriteView[]; extra: number } {
    const rows: { uid: string; name: string; leaving: boolean }[] = [];
    for (let i = 0; i < proposal.removed.length; i++) {
      const move = proposal.removed[i];
      if (move) rows.push({ uid: move.uid, name: move.name, leaving: true });
    }
    for (let i = 0; i < proposal.added.length; i++) {
      const move = proposal.added[i];
      if (move) rows.push({ uid: move.uid, name: move.name, leaving: false });
    }
    const shown = rows.slice(0, SPRITE_CAP);
    return {
      sprites: shown.map((row) => ({
        uid: `${row.leaving ? 'out' : 'in'}-${row.uid}`,
        alt: localizePokemonName(row.name, lang),
        src: getPokemonSpritePath(row.name, false),
        leaving: row.leaving,
      })),
      extra: Math.max(0, rows.length - SPRITE_CAP),
    };
  }

  function cappedLabels(labels: string[]): string {
    const shown = labels.slice(0, 8);
    const extra = labels.length > 8 ? ` +${labels.length - 8}` : '';
    return `${shown.join(', ')}${extra}`;
  }

  function proposalTooltip(proposal: SynergyRosterProposal, title: string, lang: string): { title: string; body: string } {
    const gm = game as GameRuntime | null;
    const lines: string[] = [];
    if (proposal.removed.length > 0) {
      const names = proposal.removed.map((move) => localizePokemonName(move.name, lang));
      lines.push(tr('modal.synergyOptimizeLeaves', { names: names.join(', ') }));
    }
    if (proposal.added.length > 0) {
      const names = proposal.added.map((move) => localizePokemonName(move.name, lang));
      lines.push(tr('modal.synergyOptimizeEnters', { names: names.join(', ') }));
    }
    if (proposal.gainedSynergyIds.length > 0) {
      const names = proposal.gainedSynergyIds.map((id) => synergyDisplayName(gm, id));
      lines.push(tr('modal.synergyOptimizeGained', { names: cappedLabels(names) }));
    }
    if (proposal.lostSynergyIds.length > 0) {
      const names = proposal.lostSynergyIds.map((id) => synergyDisplayName(gm, id));
      lines.push(tr('modal.synergyOptimizeLost', { names: cappedLabels(names) }));
    }
    for (let i = 0; i < SYNERGY_OBJECTIVE_KEYS.length; i++) {
      const key = SYNERGY_OBJECTIVE_KEYS[i];
      if (!key) continue;
      const delta = proposal.statDelta[key];
      if (delta == null || Math.abs(delta) < 1e-9) continue;
      const points = pctPoints(delta);
      if (points === 0) continue;
      const sign = points > 0 ? '+' : '';
      lines.push(`${statTag(key, lang)} ${sign}${points} %`);
    }
    return { title, body: lines.join('<br>') };
  }

  function optimizerIsUnlocked(): boolean {
    const gm = game as GameRuntime | null;
    return !!(gm?.unlockedFeatures?.synergyOptimizer);
  }

  function syncOptimizerUnlock(): void {
    optimizerUnlocked = optimizerIsUnlocked();
  }

  function showOptimizerLocked(): void {
    const gm = game as GameRuntime | null;
    if (!gm || typeof gm.showFeatureLockedToast !== 'function') return;
    gm.showFeatureLockedToast('synergyOptimizer');
  }

  function rosterLocked(): boolean {
    const gm = game as GameRuntime | null;
    return !!gm && gm.isTeamRosterEditLocked();
  }

  function cardFor(
    proposal: SynergyRosterProposal,
    titleKey: string,
    lang: string,
  ): OptimizerCardView {
    const title = tr(titleKey);
    const locked = rosterLocked();
    const tip = proposalTooltip(proposal, title, lang);
    const pills = buildPills(proposal, lang);
    const gm = game as GameRuntime | null;
    const gained = capNames(proposal.gainedSynergyIds.map((id) => synergyDisplayName(gm, id)));
    const lost = capNames(proposal.lostSynergyIds.map((id) => synergyDisplayName(gm, id)));
    const roster = buildSprites(proposal, lang);
    const hero = signedPoints(pctPoints(proposal.score - proposal.currentScore));
    const pillAria = pills.map((pill) => `${pill.label} ${pill.valueText}`).join(', ');
    const lockText = tr('log.teamEditLocked');
    return {
      title,
      ariaLabel: locked
        ? `${title}. ${lockText}`
        : tr('modal.synergyOptimizeCardAria', {
          title,
          delta: hero,
          stats: pillAria ? `. ${pillAria}` : '',
        }),
      hero: locked ? lockText : hero,
      heroKind: locked ? 'lock' : 'delta',
      jump: tr('modal.synergyOptimizeJump', {
        from: pctPoints(proposal.currentScore),
        to: pctPoints(proposal.score),
      }),
      pills,
      gainedText: gained.text,
      gainedExtra: gained.extra,
      lostText: lost.text,
      lostExtra: lost.extra,
      sprites: roster.sprites,
      spriteExtra: roster.extra,
      tooltipTitle: locked ? lockText : tip.title,
      tooltipBody: locked ? '' : tip.body,
      disabled: locked,
      uids: locked ? [] : proposal.uids,
    };
  }

  let optimizerView = $derived.by(() => {
    trackGameLanguage();
    const unlocked = optimizerUnlocked;
    const lang = gameLang();
    const locked = rosterLocked();
    const result = optimizeResult;
    const searching = deepRunning;
    let quiet = '';
    let best: OptimizerCardView | null = null;
    let adjust: OptimizerCardView | null = null;
    if (!searching && result) {
      const better = result.best.score > result.best.currentScore;
      if (!better) {
        quiet = `${tr('modal.synergyOptimizeAlready')} · ${pctPoints(result.best.currentScore)} %`;
      } else {
        best = cardFor(result.best, 'modal.synergyOptimizeBest', lang);
        if (result.adjust) adjust = cardFor(result.adjust, 'modal.synergyOptimizeAdjust', lang);
      }
    } else if (!searching && adjustProposal) {
      adjust = cardFor(adjustProposal, 'modal.synergyOptimizeAdjust', lang);
    }
    const searchLabel = tr('modal.synergyOptimizeSearch');
    const lockText = tr('log.teamEditLocked');
    const sprites: ReelSpriteView[] = [];
    for (let i = 0; i < deepNames.length; i++) {
      const name = deepNames[i];
      if (!name) continue;
      sprites.push({
        src: getPokemonSpritePath(name, false),
        alt: localizePokemonName(name, lang),
      });
    }
    return {
      heading: tr('modal.synergyOptimizeHeading'),
      unlocked,
      lockedLabel: tr('modal.synergyOptimizerLocked'),
      poolLabel: tr('modal.synergyPoolLabel'),
      storageLabel: tr('modal.synergyPoolStorage'),
      pensionLabel: tr('modal.synergyPoolPension'),
      rarityLabel: tr('modal.synergyRarityLabel'),
      rarities: SYNERGY_DRAW_RARITIES.map((id) => ({
        id,
        label: tr(`rarity.${id}`),
        pressed: allowedRarities.includes(id),
      })),
      regionLabel: tr('modal.synergyRegionLabel'),
      regions: SYNERGY_REGION_ORDER.map((id) => ({
        id,
        label: regionLabel(game as GameRuntime | null, id),
        pressed: allowedRegions.includes(id),
      })),
      undoLabel: tr('modal.synergyOptimizeUndo'),
      showUndo: undoReady,
      undoDisabled: locked,
      quiet,
      best,
      adjust,
      showSearch: !searching && !quiet && !best,
      searchLabel,
      searchAria: locked ? `${searchLabel}. ${lockText}` : searchLabel,
      searchDisabled: locked,
      substituteHint: tr('modal.synergySubstituteHint'),
      reel: searching && deepRound > 0
        ? {
          roundText: tr('modal.synergyOptimizeRound', { current: deepRound, total: deepRoundCount }),
          scoreText: `${signedPoints(pctPoints(deepBestScore))} %`,
          sprites,
        }
        : null,
    };
  });

  interface TeamPinView {
    uid: string;
    name: string;
    src: string;
    replaceable: boolean;
    ariaLabel: string;
  }

  let teamPins = $derived.by(() => {
    trackGameLanguage();
    const lang = gameLang();
    const kept = new Set(pinnedUids);
    const replaceableLabel = tr('modal.synergyOptimizePinOn');
    const keptLabel = tr('modal.synergyOptimizePinOff');
    const members: TeamPinView[] = [];
    const roster = team.playerTeam;
    for (let i = 0; i < roster.length; i++) {
      const creature = roster[i];
      if (!creature?.uid || !creature.name) continue;
      const name = localizePokemonName(creature.name, lang);
      const replaceable = !kept.has(creature.uid);
      members.push({
        uid: creature.uid,
        name,
        src: getPokemonSpritePath(creature.name, !!creature.isShiny),
        replaceable,
        ariaLabel: `${name}. ${replaceable ? replaceableLabel : keptLabel}`,
      });
    }
    return { label: tr('modal.synergyOptimizePins'), members };
  });

  interface SubstituteRow {
    uid: string;
    name: string;
    src: string;
  }

  interface SubstituteDialog {
    title: string;
    slotName: string;
    slotUid: string;
    rosterUids: string[];
    empty: string;
    applyLabel: string;
    lockText: string;
    closeLabel: string;
    ariaLabel: string;
    rows: SubstituteRow[];
  }

  let substituteDialog = $state<SubstituteDialog | null>(null);

  function closeSubstitutes(): void {
    substituteDialog = null;
  }

  function onSubstituteKey(event: KeyboardEvent): void {
    if (event.key !== 'Escape' || !substituteDialog) return;
    event.preventDefault();
    event.stopPropagation();
    closeSubstitutes();
  }

  function creatureIsShiny(uid: string): boolean {
    const gm = game as GameRuntime | null;
    if (!gm || !uid) return false;
    const lists = [gm.playerTeam, gm.storage, gm.pension];
    for (let i = 0; i < lists.length; i++) {
      const list = lists[i];
      if (!Array.isArray(list)) continue;
      for (let j = 0; j < list.length; j++) {
        const creature = list[j] as { uid?: string; isShiny?: boolean } | null;
        if (creature?.uid === uid) return creature.isShiny === true;
      }
    }
    return false;
  }

  function currentTeamUids(): string[] {
    const roster = team.playerTeam;
    const uids: string[] = [];
    for (let i = 0; i < roster.length; i++) {
      const uid = roster[i]?.uid;
      if (uid) uids.push(uid);
    }
    return uids;
  }

  function openSubstitutes(
    event: MouseEvent,
    slotUid: string,
    rosterUids: readonly string[],
    slotName: string,
  ): void {
    event.preventDefault();
    event.stopPropagation();
    if (!optimizerIsUnlocked()) return;
    const snap = captureSearch();
    if (!snap) {
      substituteDialog = null;
      return;
    }
    const found = synergySlotSubstitutes({
      members: snap.members,
      objective: snap.objective,
      includeStorage: snap.includeStorage,
      includePension: snap.includePension,
      allowedRarities: snap.allowedRarities,
      allowedRegions: snap.allowedRegions,
      maxTeamSize: snap.maxTeamSize,
      pinnedUids: snap.pinnedUids,
      game: snap.game,
      rosterUids,
      slotUid,
    });
    const lang = gameLang();
    const rows: SubstituteRow[] = [];
    for (let i = 0; i < found.length; i++) {
      const row = found[i];
      if (!row) continue;
      rows.push({
        uid: row.uid,
        name: localizePokemonName(row.name, lang),
        src: getPokemonSpritePath(row.name, creatureIsShiny(row.uid)),
      });
    }
    const title = tr('modal.synergySubstituteTitle');
    const rosterCopy: string[] = [];
    for (let i = 0; i < rosterUids.length; i++) {
      const id = rosterUids[i];
      if (id) rosterCopy.push(id);
    }
    substituteDialog = {
      title,
      slotName,
      slotUid,
      rosterUids: rosterCopy,
      empty: tr('modal.synergySubstituteEmpty'),
      applyLabel: tr('modal.synergySubstituteApply'),
      lockText: tr('log.teamEditLocked'),
      closeLabel: tr('common.close'),
      ariaLabel: `${title}. ${slotName}`,
      rows,
    };
  }

  function substituteAria(name: string): string {
    const dialog = substituteDialog;
    const applyLabel = dialog?.applyLabel ?? '';
    const base = `${name}. ${applyLabel}`;
    if (!rosterLocked()) return base;
    const lockText = dialog?.lockText ?? '';
    return lockText ? `${base}. ${lockText}` : base;
  }

  function applySubstitute(uid: string): void {
    const dialog = substituteDialog;
    if (!dialog || !uid || !optimizerIsUnlocked()) return;
    const next: string[] = [];
    let replaced = false;
    for (let i = 0; i < dialog.rosterUids.length; i++) {
      const id = dialog.rosterUids[i];
      if (!id) continue;
      if (id === dialog.slotUid && !replaced) {
        next.push(uid);
        replaced = true;
      } else {
        next.push(id);
      }
    }
    if (!replaced || next.length === 0) return;
    const gm = game as GameRuntime | null;
    if (!gm) return;
    cancelSearch();
    const ok = gm.applySynergyRoster(next, { includeStorage, includePension });
    if (ok) {
      undoReady = gm.hasSynergyRosterUndo();
      closeSubstitutes();
    }
  }

  function cancelDeep(): void {
    if (deepTimer) clearTimeout(deepTimer);
    deepTimer = null;
    deepSeq += 1;
    deepRunning = false;
    deepNames = [];
  }

  function cancelSearch(): void {
    if (searchTimer) clearTimeout(searchTimer);
    searchTimer = null;
    searchSeq += 1;
    pendingKey = '';
    cancelDeep();
  }

  function captureSearch(): SearchSnapshot | null {
    const gm = game as GameRuntime | null;
    if (!gm || !isModalOpen('synergyListModal')) return null;
    const stats = selectedStats.slice();
    const storageOn = includeStorage;
    const pensionOn = includePension;
    const rarities = allowedRarities.slice();
    const regions = allowedRegions.slice();
    const teamList = gm.playerTeam || [];
    const teamUidSet: Record<string, true> = {};
    for (let i = 0; i < teamList.length; i++) {
      const uid = String(teamList[i]?.uid || '');
      if (uid) teamUidSet[uid] = true;
    }
    const pins = pinnedUids.filter((uid) => teamUidSet[uid]);
    if (pins.length !== pinnedUids.length) pinnedUids = pins;
    const members = collectSynergyCandidates(teamList, gm.storage || [], gm.pension || []);
    const objective = objectiveFromStatFilters(stats);
    const maxTeamSize = getMaxTeamSize(gm);
    const key = synergyRosterSearchKey({
      members,
      objective,
      includeStorage: storageOn,
      includePension: pensionOn,
      maxTeamSize,
      pinnedUids: pins,
      unlockedRegions: getUnlockedSynergyRegionIds(gm),
      allowedRarities: rarities,
      allowedRegions: regions,
    });
    return {
      key,
      members,
      objective,
      includeStorage: storageOn,
      includePension: pensionOn,
      allowedRarities: rarities,
      allowedRegions: regions,
      maxTeamSize,
      pinnedUids: pins,
      game: gm,
    };
  }

  function scheduleSearch(): void {
    if (!optimizerIsUnlocked()) {
      cancelSearch();
      optimizeResult = null;
      adjustProposal = null;
      lastSearchKey = '';
      pendingKey = '';
      substituteDialog = null;
      return;
    }
    const snap = captureSearch();
    if (!snap) {
      cancelSearch();
      optimizeResult = null;
      adjustProposal = null;
      return;
    }
    if (snap.key === pendingKey) return;
    if (snap.key === lastSearchKey && pendingKey === '') return;
    cancelSearch();
    substituteDialog = null;
    optimizeResult = null;
    adjustProposal = null;
    pendingKey = snap.key;
    const seq = ++searchSeq;
    searchTimer = setTimeout(() => {
      searchTimer = null;
      if (seq !== searchSeq || !isModalOpen('synergyListModal')) {
        if (seq === searchSeq) pendingKey = '';
        return;
      }
      try {
        const result = optimizeSynergyRoster({
          members: snap.members,
          objective: snap.objective,
          includeStorage: snap.includeStorage,
          includePension: snap.includePension,
          allowedRarities: snap.allowedRarities,
          allowedRegions: snap.allowedRegions,
          maxTeamSize: snap.maxTeamSize,
          pinnedUids: snap.pinnedUids,
          game: snap.game,
        }, { rounds: 0 });
        adjustProposal = result.adjust;
        lastSearchKey = snap.key;
      } catch {
        adjustProposal = null;
      }
      if (seq === searchSeq) pendingKey = '';
    }, 0);
  }

  function startDeepSearch(): void {
    if (!optimizerIsUnlocked() || deepRunning || rosterLocked()) return;
    const snap = captureSearch();
    if (!snap) return;
    if (searchTimer) clearTimeout(searchTimer);
    searchTimer = null;
    searchSeq += 1;
    pendingKey = '';
    cancelDeep();
    lastSearchKey = snap.key;
    optimizeResult = null;
    adjustProposal = null;
    deepRunning = true;
    deepRound = 0;
    deepRoundCount = SYNERGY_DEEP_ROUNDS;
    deepBestScore = 0;
    deepNames = [];
    const seq = deepSeq;
    const search = openSynergyDeepSearch({
      members: snap.members,
      objective: snap.objective,
      includeStorage: snap.includeStorage,
      includePension: snap.includePension,
      allowedRarities: snap.allowedRarities,
      allowedRegions: snap.allowedRegions,
      maxTeamSize: snap.maxTeamSize,
      pinnedUids: snap.pinnedUids,
      game: snap.game,
    }, SYNERGY_DEEP_ROUNDS);
    const pump = (): void => {
      if (seq !== deepSeq || !isModalOpen('synergyListModal')) return;
      const started = performance.now();
      let info: ReturnType<typeof search.next> = null;
      try {
        info = search.next();
      } catch {
        deepRunning = false;
        deepNames = [];
        return;
      }
      if (!info) {
        try {
          optimizeResult = search.result();
        } catch {
          optimizeResult = null;
        }
        deepRunning = false;
        deepNames = [];
        return;
      }
      deepRound = info.round;
      deepRoundCount = info.roundCount;
      deepBestScore = info.bestScore;
      deepNames = info.names.slice();
      const wait = Math.max(16, 90 - (performance.now() - started));
      deepTimer = setTimeout(pump, wait);
    };
    pump();
  }

  function refreshUndo(): void {
    const gm = game as GameRuntime | null;
    if (!gm || typeof gm.hasSynergyRosterUndo !== 'function') {
      undoReady = false;
      return;
    }
    const available = gm.hasSynergyRosterUndo();
    undoReady = isModalOpen('synergyListModal') && available;
  }

  function onRosterEvent(evt: GameEvent): void {
    if (evt.type === Evt.MODAL_OPENED || evt.type === Evt.MODAL_CLOSED) {
      if (evt.modalId !== 'synergyListModal') return;
      if (evt.type === Evt.MODAL_CLOSED) {
        cancelSearch();
        optimizeResult = null;
        adjustProposal = null;
        lastSearchKey = '';
        undoReady = false;
        substituteDialog = null;
        return;
      }
    }
    syncOptimizerUnlock();
    if (!optimizerUnlocked) {
      cancelSearch();
      optimizeResult = null;
      adjustProposal = null;
      lastSearchKey = '';
      undoReady = false;
      substituteDialog = null;
      return;
    }
    refreshUndo();
    scheduleSearch();
  }

  function clearStatFilters(): void {
    if (selectedStats.length === 0) return;
    selectedStats = [];
    scheduleSearch();
  }

  function toggleStat(id: string): void {
    selectedStats = selectedStats.includes(id)
      ? selectedStats.filter((stat) => stat !== id)
      : [...selectedStats, id];
    scheduleSearch();
  }

  function togglePool(zone: 'storage' | 'pension'): void {
    if (zone === 'storage') includeStorage = !includeStorage;
    else includePension = !includePension;
    writeOptimizerPools(includeStorage, includePension, allowedRarities, allowedRegions);
    scheduleSearch();
  }

  function toggleRarity(id: string): void {
    allowedRarities = allowedRarities.includes(id)
      ? allowedRarities.filter((rarity) => rarity !== id)
      : [...allowedRarities, id];
    writeOptimizerPools(includeStorage, includePension, allowedRarities, allowedRegions);
    scheduleSearch();
  }

  function toggleRegion(id: string): void {
    allowedRegions = allowedRegions.includes(id)
      ? allowedRegions.filter((region) => region !== id)
      : [...allowedRegions, id];
    writeOptimizerPools(includeStorage, includePension, allowedRarities, allowedRegions);
    scheduleSearch();
  }

  function togglePin(uid: string): void {
    pinnedUids = pinnedUids.includes(uid)
      ? pinnedUids.filter((id) => id !== uid)
      : [...pinnedUids, uid];
    scheduleSearch();
  }

  function applyProposal(uids: readonly string[]): void {
    if (!optimizerUnlocked || deepRunning || uids.length === 0) return;
    const gm = game as GameRuntime | null;
    if (!gm) return;
    const ok = gm.applySynergyRoster(uids, { includeStorage, includePension });
    if (ok) undoReady = gm.hasSynergyRosterUndo();
  }

  function undoProposal(): void {
    if (!optimizerUnlocked) return;
    const gm = game as GameRuntime | null;
    if (!gm) return;
    const ok = gm.undoSynergyRoster();
    if (ok) undoReady = false;
  }

  function showProposalTip(event: MouseEvent | FocusEvent, card: OptimizerCardView): void {
    if (!card.tooltipTitle && !card.tooltipBody) return;
    showGameTooltip(event, card.tooltipTitle, card.tooltipBody);
  }

  useFacadeSubscription(
    [Evt.TEAM_CHANGED, Evt.STORAGE_CHANGED, Evt.SHOP_CHANGED, Evt.MODAL_OPENED, Evt.MODAL_CLOSED],
    onRosterEvent,
  );
  onDestroy(cancelSearch);

  if (isModalOpen('synergyListModal') && optimizerIsUnlocked()) {
    refreshUndo();
    scheduleSearch();
  }
</script>

