            aria-label={pin.ariaLabel}
            onclick={() => togglePin(pin.uid)}
            oncontextmenu={(event) => openSubstitutes(event, pin.uid, currentTeamUids(), pin.name)}
          >
            <img class="synergy-opt-sprite" src={pin.src} alt={pin.name} />
          </button>
        {/each}
      </div>
    {/if}
    {#if optimizerView.quiet}
      <p class="synergy-optimizer-quiet">{optimizerView.quiet}</p>
    {:else}
      <div class="synergy-optimizer-actions">
        {#if optimizerView.reel}
          <div class="synergy-optimizer-reel">
            <div class="synergy-optimizer-reel-meta">
              {#key optimizerView.reel.scoreText}
                <span class="synergy-opt-hero is-delta synergy-optimizer-reel-score">{optimizerView.reel.scoreText}</span>
              {/key}
              {#key optimizerView.reel.roundText}
                <span class="synergy-optimizer-reel-round">{optimizerView.reel.roundText}</span>
              {/key}
            </div>
            <div class="synergy-optimizer-reel-window">
              <div class="synergy-optimizer-reel-track">
                {#each [0, 1] as copy (copy)}
                  <div class="synergy-optimizer-reel-row" aria-hidden={copy === 1 ? true : undefined}>
                    {#each optimizerView.reel.sprites as sprite, index (`${copy}-${index}`)}
                      <img class="synergy-opt-sprite" src={sprite.src} alt={copy === 0 ? sprite.alt : ''} />
                    {/each}
                  </div>
                {/each}
              </div>
              {#key optimizerView.reel.roundText}
                <span class="synergy-optimizer-reel-flash" aria-hidden="true"></span>
              {/key}
            </div>
          </div>
        {:else if optimizerView.showSearch}
          <button
            type="button"
            class="synergy-optimizer-search"
            aria-label={optimizerView.searchAria}
            disabled={optimizerView.searchDisabled}
            onclick={startDeepSearch}
          >
            {optimizerView.searchLabel}
          </button>
        {/if}
        {#if optimizerView.best}
          {@render renderOptimizerCard(optimizerView.best)}
        {/if}
        {#if optimizerView.adjust}
          {@render renderOptimizerCard(optimizerView.adjust)}
        {/if}
      </div>
      {#if substituteDialog}
        <div class="synergy-substitute-backdrop">
          <button
            type="button"
            class="synergy-substitute-dismiss"
            aria-label={substituteDialog.closeLabel}
            onclick={closeSubstitutes}
          ></button>
          <div
            class="synergy-substitute"
            role="dialog"
            aria-modal="true"
            aria-label={substituteDialog.ariaLabel}
            tabindex="-1"
          >
            <div class="synergy-substitute-head">
              <p class="synergy-substitute-title">{substituteDialog.title}</p>
              <button
                type="button"
                class="synergy-substitute-close"
                aria-label={substituteDialog.closeLabel}
                onclick={closeSubstitutes}
              >
                ✕
              </button>
            </div>
            <p class="synergy-substitute-slot">{substituteDialog.slotName}</p>
            <p class="synergy-substitute-apply">{substituteDialog.applyLabel}</p>
            {#if substituteDialog.rows.length === 0}
              <p class="synergy-substitute-empty">{substituteDialog.empty}</p>
            {:else}
              <ul class="synergy-substitute-list">
                {#each substituteDialog.rows as row (row.uid)}
                  <li>
                    <button
                      type="button"
                      class="synergy-substitute-row"
                      disabled={rosterLocked()}
                      aria-label={substituteAria(row.name)}
                      onclick={() => applySubstitute(row.uid)}
                    >
                      <img class="synergy-opt-sprite" src={row.src} alt="" />
                      <span>{row.name}</span>
                    </button>
                  </li>
                {/each}
              </ul>
            {/if}
          </div>
        </div>
      {/if}
    {/if}
    {:else}
      <button type="button" class="synergy-optimizer-lock" onclick={showOptimizerLocked}>
        {optimizerView.lockedLabel}
      </button>
    {/if}
  </section>
</div>

<!-- Liste des synergies structurée en sections -->
<div id="synergyListContent" class="synergy-guide-sections">
  {#if activeCards.length > 0}
    <div class="synergy-guide-section">
      <div class="synergy-guide-section-title">
        <span class="synergy-section-dot is-active"></span>
        <span>{activeSectionLabel()} · {activeCards.length}</span>
      </div>
      <div class="synergy-guide-cards-list">
        {#each activeCards as card (card.id)}
          {@render renderCard(card)}
        {/each}
      </div>
    </div>
  {/if}

  {#if almostCards.length > 0}
    <div class="synergy-guide-section">
      <div class="synergy-guide-section-title">
        <span class="synergy-section-dot is-almost"></span>
        <span>{almostSectionLabel()} · {almostCards.length}</span>
      </div>
      <div class="synergy-guide-cards-list">
        {#each almostCards as card (card.id)}
          {@render renderCard(card)}
        {/each}
      </div>
    </div>
  {/if}

  {#if otherCards.length > 0}
    {#if effectiveShowOthers}
      <div class="synergy-guide-section synergy-guide-section--others">
        <div class="synergy-guide-section-header">
          <div class="synergy-guide-section-title">
            <span class="synergy-section-dot is-other"></span>
            <span>{otherSectionLabel()} · {otherCards.length}</span>
          </div>
          {#if activeCards.length > 0 || almostCards.length > 0}
            <button
              type="button"
              class="synergy-toggle-others-btn"
              onclick={() => { userToggledOthers = false; }}
            >
              {gameLang() === 'fr' ? '▲ Masquer les autres' : '▲ Hide other synergies'}
            </button>
          {/if}
        </div>
        <div class="synergy-guide-cards-list">
          {#each otherCards as card (card.id)}
            {@render renderCard(card)}
          {/each}
        </div>
      </div>
    {:else}
      <div class="synergy-guide-section synergy-guide-section--others-collapsed">
        <button
          type="button"
          class="synergy-expand-others-bar"
          onclick={() => { userToggledOthers = true; }}
        >
          <span>{gameLang() === 'fr' ? `Afficher les autres (${otherCards.length})` : `Show other synergies (${otherCards.length})`}</span>
          <span class="synergy-expand-others-arrow">▼</span>
        </button>
      </div>
    {/if}
  {/if}

  {#if activeCards.length === 0 && almostCards.length === 0 && otherCards.length === 0}
    <div class="synergy-empty-filter-msg">
      {gameLang() === 'fr' ? 'Aucune synergie ne correspond à ce filtre.' : 'No synergies match this filter.'}
    </div>
  {/if}
</div>
